import React from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { type Question, type Category } from '@/services/api.ts';

interface ViewQuestionProps {
  question: Question | null;
  categories: Category[];
  isOpen: boolean;
  onClose: () => void;
}

export function ViewQuestion({
  question,
  categories,
  isOpen,
  onClose,
}: ViewQuestionProps) {
  if (!question) return null;

  const getCategoryName = (categoryId: string) => {
    const category = categories.find((cat) => cat._id === categoryId);
    return category?.name || categoryId;
  };

  const getSubCategoryName = (
    mainCategoryId: string,
    subCategoryId: string
  ) => {
    const category = categories.find((cat) => cat._id === mainCategoryId);
    const subCategory = category?.subCategories.find(
      (sub) => sub._id === subCategoryId
    );
    return subCategory?.name || subCategoryId;
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-3xl">
        <DialogHeader>
          <DialogTitle>Question Details</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <Card>
            <CardContent className="pt-6">
              <div className="grid gap-4">
                <div>
                  <h3 className="font-semibold">Question Type</h3>
                  <Badge variant="outline" className="mt-1">
                    {question.questionType === 'multiple-choice-single'
                      ? 'Multiple Choice Single Answer'
                      : question.questionType === 'multiple-choice-multiple'
                      ? 'Multiple Choice Multiple Answers'
                      : question.questionType === 'true-false'
                      ? 'True/False'
                      : question.questionType === 'short-answer'
                      ? 'Short Answer'
                      : 'Essay'}
                  </Badge>
                </div>

                <div>
                  <h3 className="font-semibold">Question</h3>
                  <p className="text-gray-600">{question.questionText}</p>
                </div>

                <div>
                  <h3 className="font-semibold">Answer</h3>
                  {[
                    'multiple-choice-single',
                    'multiple-choice-multiple',
                    'true-false',
                  ].includes(question.questionType) ? (
                    <div className="space-y-2">
                      {question.options?.map((option, idx) => (
                        <div
                          key={idx}
                          className={`flex items-center ${
                            option.isCorrect ? 'text-green-600' : ''
                          }`}
                        >
                          <span className="mr-2">{idx + 1}.</span>
                          <span>{option.text}</span>
                          {option.isCorrect && (
                            <Badge className="ml-2">Correct</Badge>
                          )}
                        </div>
                      ))}
                    </div>
                  ) : question.questionType === 'essay' ? (
                    <div className="space-y-2">
                      <div className="text-green-600">
                        <span className="font-medium">Answer:</span>
                        <p className="mt-1">
                          {question.answer || 'No specific answer provided'}
                        </p>
                      </div>
                      <Badge className="mt-1">Essay Question</Badge>
                    </div>
                  ) : (
                    <div className="space-y-2">
                      <div className="text-green-600">
                        <span className="font-medium">Answer:</span>
                        <p className="mt-1">{question.answer || '-'}</p>
                      </div>
                      <Badge className="mt-1">Short Answer</Badge>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <h3 className="font-semibold">Main Category</h3>
                    <p className="text-gray-600">
                      {getCategoryName(question.mainCategory)}
                    </p>
                  </div>
                  <div>
                    <h3 className="font-semibold">Sub Category</h3>
                    <p className="text-gray-600">
                      {getSubCategoryName(
                        question.mainCategory,
                        question.subCategory
                      )}
                    </p>
                  </div>
                  <div>
                    <h3 className="font-semibold">Level</h3>
                    <p className="text-gray-600">{question.level}</p>
                  </div>
                  <div>
                    <h3 className="font-semibold">Status</h3>
                    <Badge
                      variant={
                        question.status === 'Active' ? 'default' : 'destructive'
                      }
                    >
                      {question.status}
                    </Badge>
                  </div>
                  <div>
                    <h3 className="font-semibold">Marks</h3>
                    <p className="text-gray-600">{question.marks}</p>
                  </div>
                </div>

                {question.explanation && (
                  <div>
                    <h3 className="font-semibold">Explanation</h3>
                    <p className="text-gray-600">{question.explanation}</p>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        </div>
      </DialogContent>
    </Dialog>
  );
}
