"use client"

import * as React from "react"
import {
  type ColumnDef,
  type ColumnFiltersState,
  type SortingState,
  type VisibilityState,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table"
import { Edit, Eye, Trash2 } from "lucide-react"
import { toast } from "react-toastify"
import { useNavigate } from "react-router-dom"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Badge } from "@/components/ui/badge"
import subAdminService from "@/services/subAdminService"

// Define the data type for sub admins
export type SubAdmin = {
  _id: string
  firstName: string
  lastName: string
  mobile: string
  email: string
  status: "active" | "inactive"
  groups: string[]
}

export function SubAdminsTable() {
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([])
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>({})
  const [rowSelection, setRowSelection] = React.useState({})
  const [globalFilter, setGlobalFilter] = React.useState("")
  const [pageSize, setPageSize] = React.useState(10)
  const [subAdmins, setSubAdmins] = React.useState<SubAdmin[]>([])
  const [loading, setLoading] = React.useState(true)
  const navigate = useNavigate()

  // Fetch sub-admins data
  React.useEffect(() => {
    const fetchSubAdmins = async () => {
      try {
        const data = await subAdminService.getAllSubAdmins()
        setSubAdmins(data)
      } catch (error) {
        console.error('Error fetching sub-admins:', error)
        toast.error('Failed to fetch sub-admins')
      } finally {
        setLoading(false)
      }
    }

    fetchSubAdmins()
  }, [])

  // Handle delete sub-admin
  const handleDelete = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this sub-admin?')) {
      try {
        await subAdminService.deleteSubAdmin(id)
        setSubAdmins(subAdmins.filter(admin => admin._id !== id))
        toast.success('Sub-admin deleted successfully')
      } catch (error) {
        console.error('Error deleting sub-admin:', error)
        toast.error('Failed to delete sub-admin')
      }
    }
  }

  // Handle edit sub-admin
  const handleEdit = (id: string) => {
    navigate(`/admin/sub-admins/${id}/edit`)
  }

  // Handle view sub-admin
  const handleView = (id: string) => {
    navigate(`/admin/sub-admins/${id}`)  
  }

  // Define columns
  const columns: ColumnDef<SubAdmin>[] = [
    {
      accessorKey: "_id",
      header: "ID",
      cell: ({ row }) => <div>{row.index + 1}</div>,
    },
    {
      id: "fullName",
      header: "Full Name",
      cell: ({ row }) => {
        const firstName = row.original.firstName || '';
        const lastName = row.original.lastName || '';
        return <div className="capitalize">{`${firstName} ${lastName}`}</div>;
      },
    },
    {
      accessorKey: "mobile",
      header: "Mobile",
    },
    {
      accessorKey: "email",
      header: "Email",
    },
    {
      accessorKey: "status",
      header: "Status",
      cell: ({ row }) => {
        const status = row.getValue("status") as string
        return (
          <Badge className={status === "active" ? "bg-green-500" : "bg-gray-500"}>
            {status === "active" ? "Active" : "Inactive"}
          </Badge>
        )
      },
    },
    {
      id: "actions",
      header: "Actions",
      cell: ({ row }) => {
        const subAdmin = row.original
        return (
          <div className="flex gap-2">
            <Button 
              variant="outline" 
              size="icon" 
              className="h-8 w-8 bg-rose-500 text-white hover:bg-rose-600"
              onClick={() => handleView(subAdmin._id)}
            >
              <Eye className="h-4 w-4" />
              <span className="sr-only">View</span>
            </Button>
            <Button 
              variant="outline" 
              size="icon" 
              className="h-8 w-8 bg-sky-500 text-white hover:bg-sky-600"
              onClick={() => handleEdit(subAdmin._id)}
            >
              <Edit className="h-4 w-4" />
              <span className="sr-only">Edit</span>
            </Button>
            <Button 
              variant="outline" 
              size="icon" 
              className="h-8 w-8 bg-red-500 text-white hover:bg-red-600"
              onClick={() => handleDelete(subAdmin._id)}
            >
              <Trash2 className="h-4 w-4" />
              <span className="sr-only">Delete</span>
            </Button>
          </div>
        )
      },
    },
  ]

  const table = useReactTable({
    data: subAdmins,
    columns,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    state: {
      sorting,
      columnFilters,
      columnVisibility,
      rowSelection,
      globalFilter,
      pagination: {
        pageSize,
        pageIndex: 0,
      },
    },
    globalFilterFn: (row, columnId, filterValue) => {
      const safeValue = (() => {
        const value = row.getValue(columnId)
        return typeof value === "number" ? String(value) : (value as string)
      })()

      return safeValue?.toLowerCase().includes(filterValue.toLowerCase())
    },
  })

  if (loading) {
    return <div>Loading...</div>
  }

  return (
    <div className="w-full border bg-background p-4 rounded-md">
      <div className="">
        <div className="flex items-center justify-between p-4">
          <div className="flex items-center gap-2">
            <div className="text-sm">Show</div>
            <select
              className="h-8 rounded-md border bg-background border-input px-3 py-1"
              value={pageSize}
              onChange={(e) => {
                setPageSize(Number(e.target.value))
              }}
            >
              {[10, 20, 30, 40, 50].map((size) => (
                <option key={size} value={size}>
                  {size}
                </option>
              ))}
            </select>
            <div className="text-sm">entries</div>
          </div>
          <div className="flex items-center gap-2">
            <div className="text-sm">Search:</div>
            <Input
              placeholder="Search..."
              value={globalFilter ?? ""}
              onChange={(e) => setGlobalFilter(e.target.value)}
              className="max-w-sm"
            />
          </div>
        </div>

        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  return (
                    <TableHead key={header.id}>
                      {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                    </TableHead>
                  )
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow key={row.id} data-state={row.getIsSelected() && "selected"}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>{flexRender(cell.column.columnDef.cell, cell.getContext())}</TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className="h-24 text-center">
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <div className="flex items-center justify-between space-x-2 py-4">
        <div className="text-sm text-muted-foreground">
          Showing {table.getState().pagination.pageIndex * pageSize + 1} to{" "}
          {Math.min((table.getState().pagination.pageIndex + 1) * pageSize, table.getFilteredRowModel().rows.length)} of{" "}
          {table.getFilteredRowModel().rows.length} entries
        </div>
        <div className="flex items-center space-x-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            Previous
          </Button>
          <div className="flex items-center gap-1">
            {Array.from({ length: table.getPageCount() }, (_, i) => (
              <Button
                key={i}
                variant={table.getState().pagination.pageIndex === i ? "default" : "outline"}
                size="sm"
                onClick={() => table.setPageIndex(i)}
              >
                {i + 1}
              </Button>
            ))}
          </div>
          <Button variant="outline" size="sm" onClick={() => table.nextPage()} disabled={!table.getCanNextPage()}>
            Next
          </Button>
        </div>
      </div>
    </div>
  )
}

