'use client';

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { ArrowLeft } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import subAdminService from '@/services/subAdminService';
import { groupService } from '@/services/api.ts';

export default function ViewSubAdmin() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [subAdmin, setSubAdmin] = useState(null);
  const [groups, setGroups] = useState([]);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    questions: { active: 0, deactive: 0, total: 0 },
    papers: { active: 0, deactive: 0, total: 0 }
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [subAdminData, groupsData, statsData] = await Promise.all([
          subAdminService.getSubAdmin(id),
          groupService.getAllGroups(),
          subAdminService.getSubAdminStats(id)
        ]);
        
        setSubAdmin(subAdminData);
        setGroups(groupsData);
        setStats(statsData);
      } catch (error) {
        console.error('Error fetching data:', error);
        toast.error('Failed to fetch sub-admin details');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [id]);

  if (loading) {
    return <div>Loading...</div>;
  }

  if (!subAdmin) {
    return <div>Sub-admin not found</div>;
  }

  // Get group names for the sub-admin's groups
  const getGroupNames = () => {
    if (!subAdmin.groups || !Array.isArray(subAdmin.groups)) return [];
    return subAdmin.groups.map(groupId => {
      const group = groups.find(g => g._id === groupId);
      return group ? group.name : 'Unknown Group';
    });
  };

  // Table data
  const tableData = [
    {
      type: 'Questions',
      active: stats.questions.active,
      deactive: stats.questions.deactive,
      total: stats.questions.total
    },
    {
      type: 'Papers',
      active: stats.papers.active,
      deactive: stats.papers.deactive,
      total: stats.papers.total
    }
  ];

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-semibold">Full Sub Admin Detail</h1>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            onClick={() => navigate('/admin/sub-admins')}
            className="flex items-center gap-2"
          >
            <ArrowLeft className="h-4 w-4" />
            Back to Sub-admins
          </Button>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Complete sub admin details</CardTitle>
        </CardHeader>
        <CardContent className="p-6">
          <div className="grid gap-6">
            <div className="grid gap-4">
              <div className="grid grid-cols-[200px_1fr] items-center">
                <span className="font-medium">Full Name</span>
                <span>{`${subAdmin.firstName} ${subAdmin.lastName}`}</span>
              </div>
              <div className="grid grid-cols-[200px_1fr] items-center">
                <span className="font-medium">Email id</span>
                <span>{subAdmin.email}</span>
              </div>
              <div className="grid grid-cols-[200px_1fr] items-center">
                <span className="font-medium">Mobile Number</span>
                <span>{subAdmin.mobile}</span>
              </div>
              <div className="grid grid-cols-[200px_1fr] items-center">
                <span className="font-medium">Status</span>
                <Badge className={subAdmin.status === "active" ? "bg-green-500" : "bg-gray-500"}>
                  {subAdmin.status === "active" ? "Active" : "Inactive"}
                </Badge>
              </div>
              <div className="grid grid-cols-[200px_1fr] items-start">
                <span className="font-medium">Allowed Groups</span>
                <div className="flex flex-col gap-1">
                  {getGroupNames().map((name, index) => (
                    <span key={index}>{name}</span>
                  ))}
                </div>
              </div>
            </div>

            <div className="mt-6">
              <Table>
                <TableHeader className="bg-black">
                  <TableRow>
                    <TableHead className="text-white">Type</TableHead>
                    <TableHead className="text-white">Active</TableHead>
                    <TableHead className="text-white">Deactive</TableHead>
                    <TableHead className="text-white">Total</TableHead>
                    <TableHead className="text-white">Action</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {tableData.map((row, index) => (
                    <TableRow key={index} className="bg-[#B8DDE0]">
                      <TableCell>{row.type}</TableCell>
                      <TableCell>{row.active}</TableCell>
                      <TableCell>{row.deactive}</TableCell>
                      <TableCell>{row.total}</TableCell>
                      <TableCell>
                        <Button variant="link" className="text-blue-600 hover:text-blue-800">
                          Login as Subadmin
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </div>
        </CardContent>
      </Card>

      <div className="flex justify-start gap-2 mt-4">
        <Button
          variant="outline"
          onClick={() => navigate('/admin/sub-admins')}
          className="bg-rose-500 text-white hover:bg-rose-600"
        >
          Go back
        </Button>
        <Button
          variant="outline"
          onClick={() => navigate(`/admin/sub-admins/${id}/edit`)}
          className="bg-blue-500 text-white hover:bg-blue-600"
        >
          Edit Sub Admin Details
        </Button>
        <Button
          variant="outline"
          onClick={() => {
            if (window.confirm('Are you sure you want to delete this sub-admin?')) {
              subAdminService.deleteSubAdmin(id)
                .then(() => {
                  toast.success('Sub-admin deleted successfully');
                  navigate('/admin/sub-admins');
                })
                .catch(error => {
                  console.error('Error deleting sub-admin:', error);
                  toast.error('Failed to delete sub-admin');
                });
            }
          }}
          className="bg-red-500 text-white hover:bg-red-600"
        >
          Delete Sub Admin
        </Button>
      </div>
    </div>
  );
} 