'use client';

import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Label } from '@/components/ui/label';
import { ChevronLeft } from 'lucide-react';
import type { QuestionOptions } from './question-options';
import { Checkbox } from '@/components/ui/checkbox';
import { categoryService, questionService } from '@/services/api.ts';

interface QuestionFormProps {
  options: QuestionOptions;
  onBack: () => void;
  onSubmit?: (formData: any) => void;
}

export function QuestionForm({ options, onBack, onSubmit }: QuestionFormProps) {
  const navigate = useNavigate();
  const hasOptions = (type: string) => {
    return (
      type === 'multiple-choice-single' ||
      type === 'multiple-choice-multiple' ||
      type === 'true-false'
    );
  };

  const [categories, setCategories] = useState<{
    mainCategories: Array<{ id: string; name: string }>;
    subCategories: Array<{ id: string; name: string; mainCategoryId: string }>;
    levels: string[];
  }>({
    mainCategories: [],
    subCategories: [],
    levels: [],
  });

  const [formData, setFormData] = useState({
    category: '',
    subCategory: '',
    level: 'top-simple',
    question: '',
    options:
      options.questionType === 'true-false'
        ? ['True', 'False']
        : Array(options.numberOfOptions).fill(''),
    correctOptions:
      options.questionType === 'multiple-choice-multiple'
        ? ([] as number[])
        : [0],
    explanation: '',
    marks: 1,
  });

  useEffect(() => {
    const loadCategories = async () => {
      try {
        const data = await categoryService.getAllCategories();
        // Transform the category data into the expected format
        const transformedData = {
          mainCategories: data.map((category) => ({
            id: category._id,
            name: category.name,
          })),
          subCategories: data.flatMap((category) =>
            category.subCategories.map((sub) => ({
              id: sub._id,
              name: sub.name,
              mainCategoryId: category._id,
            }))
          ),
          levels: ['top-simple', 'top-medium', 'top-hard'], // Default levels
        };
        setCategories(transformedData);
      } catch (error) {
        toast.error('Error loading categories');
        console.error('Error loading categories:', error);
      }
    };
    loadCategories();
  }, []);

  // Reset sub-category when main category changes
  const handleMainCategoryChange = (value: string) => {
    setFormData((prev) => ({
      ...prev,
      category: value,
      subCategory: '', // Reset sub-category when main category changes
    }));
  };

  // Get filtered sub-categories based on selected main category
  const getFilteredSubCategories = () => {
    return categories.subCategories.filter(
      (sub) => sub.mainCategoryId === formData.category
    );
  };

  const handleOptionChange = (index: number, value: string) => {
    const newOptions = [...formData.options];
    newOptions[index] = value;
    setFormData({ ...formData, options: newOptions });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      // Validation
      if (!formData.question.trim()) {
        toast.error('Question text is required');
        return;
      }

      if (!formData.category) {
        toast.error('Category is required');
        return;
      }

      if (!formData.subCategory) {
        toast.error('Sub-category is required');
        return;
      }

      if (hasOptions(options.questionType)) {
        const emptyOptions = formData.options.some((opt) => !opt.trim());
        if (emptyOptions) {
          toast.error('All options must have text');
          return;
        }

        if (
          options.questionType === 'multiple-choice-multiple' &&
          formData.correctOptions.length === 0
        ) {
          toast.error('Please select at least one correct option');
          return;
        }
      }

      // Validate explanation for short-answer and essay questions
      if (
        ['short-answer', 'essay'].includes(options.questionType) &&
        !formData.explanation?.trim()
      ) {
        toast.error(
          'Explanation is required for short-answer and essay questions'
        );
        return;
      }

      // Create question data object
      const questionData = {
        questionText: formData.question,
        questionType: options.questionType,
        options: hasOptions(options.questionType)
          ? formData.options.map((text, index) => ({
              text,
              isCorrect:
                options.questionType === 'multiple-choice-multiple'
                  ? formData.correctOptions.includes(index)
                  : formData.correctOptions[0] === index,
            }))
          : undefined,
        answer: ['true-false', 'short-answer'].includes(options.questionType)
          ? formData.answer
          : undefined,
        marks: formData.marks,
        explanation: formData.explanation,
        mainCategory: formData.category,
        subCategory: formData.subCategory,
        level: formData.level,
      };

      await questionService.createQuestion(questionData);
      toast.success('Question added successfully');

      if (onSubmit) {
        onSubmit(questionData);
      }

      navigate('/admin/questions');
    } catch (error) {
      toast.error('Error adding question');
      console.error('Error:', error);
    }
  };

  return (
    <Card className="w-full max-w-5xl mx-auto bg-background border-border">
      <CardHeader className="border-b border-border flex flex-row items-center justify-between">
        <div className="flex items-center">
          <Button variant="ghost" size="icon" onClick={onBack} className="mr-2">
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <CardTitle className="text-xl text-foreground">
            Add new question
            <span className="text-sm font-normal text-muted-foreground ml-2">
              {options.questionType === 'multiple-choice-single'
                ? 'Multiple Choice Single Answer'
                : options.questionType}
            </span>
          </CardTitle>
        </div>
      </CardHeader>
      <CardContent className="pt-6">
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-4">
            <div className="space-y-2">
              <label
                htmlFor="category"
                className="text-sm font-medium text-foreground"
              >
                Select Category{' '}
                <Link
                  to="/admin/categories"
                  className="text-xs text-muted-foreground"
                >
                  - - - - - - Click to Add new Category
                </Link>
              </label>
              <Select
                value={formData.category}
                onValueChange={handleMainCategoryChange}
              >
                <SelectTrigger id="category" className="w-full">
                  <SelectValue placeholder="Select main category" />
                </SelectTrigger>
                <SelectContent>
                  {categories.mainCategories.map((category) => (
                    <SelectItem key={category.id} value={category.id}>
                      {category.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <label
                htmlFor="subCategory"
                className="text-sm font-medium text-foreground"
              >
                Sub Category{' '}
                <Link
                  to="/admin/categories"
                  className="text-xs text-muted-foreground"
                >
                  - - - - - - Click to Add new Subcategory
                </Link>
              </label>
              <Select
                value={formData.subCategory}
                onValueChange={(value) =>
                  setFormData((prev) => ({ ...prev, subCategory: value }))
                }
                disabled={!formData.category}
              >
                <SelectTrigger id="subCategory" className="w-full">
                  <SelectValue placeholder="Select sub category" />
                </SelectTrigger>
                <SelectContent>
                  {getFilteredSubCategories().map((subCategory) => (
                    <SelectItem key={subCategory.id} value={subCategory.id}>
                      {subCategory.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <label
                htmlFor="level"
                className="text-sm font-medium text-foreground"
              >
                Select Level
              </label>
              <Select
                value={formData.level}
                onValueChange={(value) =>
                  setFormData({ ...formData, level: value })
                }
              >
                <SelectTrigger id="level" className="w-full">
                  <SelectValue placeholder="Select difficulty level" />
                </SelectTrigger>
                <SelectContent>
                  {categories.levels.map((level) => (
                    <SelectItem key={level} value={level}>
                      {level}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <label
              htmlFor="question"
              className="text-sm font-medium text-foreground"
            >
              Question
            </label>
            <div className="border border-border rounded-md">
              <div className="flex items-center p-2 border-b border-border">
                {/* Simplified toolbar */}
                <div className="flex gap-1">
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8"
                  >
                    <span className="font-bold">B</span>
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8"
                  >
                    <span className="italic">I</span>
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8"
                  >
                    <span className="underline">U</span>
                  </Button>
                </div>
              </div>
              <Textarea
                id="question"
                value={formData.question}
                onChange={(e) =>
                  setFormData({ ...formData, question: e.target.value })
                }
                placeholder="Enter your question here..."
                className="min-h-[100px] border-0 focus-visible:ring-0 focus-visible:ring-offset-0"
              />
            </div>
          </div>

          {hasOptions(options.questionType) && (
            <div className="space-y-4">
              <div className="flex items-center">
                <h3 className="text-sm font-medium text-foreground">
                  Options ({options.numberOfOptions})
                </h3>
              </div>
              {options.questionType === 'multiple-choice-multiple' ? (
                // Checkbox group for multiple correct answers
                <div className="space-y-4">
                  {Array.from({ length: options.numberOfOptions }).map(
                    (_, index) => (
                      <div key={index} className="flex items-start gap-4">
                        <div className="flex items-center h-10 mt-2">
                          <Checkbox
                            id={`option-${index}`}
                            checked={formData.correctOptions.includes(index)}
                            onCheckedChange={(checked) => {
                              setFormData((prev) => ({
                                ...prev,
                                correctOptions: checked
                                  ? [...prev.correctOptions, index]
                                  : prev.correctOptions.filter(
                                      (i) => i !== index
                                    ),
                              }));
                            }}
                          />
                          <Label
                            htmlFor={`option-${index}`}
                            className="ml-2 text-xs"
                          >
                            Correct Option
                          </Label>
                        </div>
                        <div className="flex-1">
                          <div className="border border-border rounded-md">
                            <div className="flex items-center p-2 border-b border-border">
                              {/* Toolbar */}
                            </div>
                            <Textarea
                              value={formData.options[index]}
                              onChange={(e) =>
                                handleOptionChange(index, e.target.value)
                              }
                              placeholder={`Enter option ${index + 1}`}
                              className="min-h-[80px] border-0 focus-visible:ring-0 focus-visible:ring-offset-0"
                            />
                          </div>
                        </div>
                      </div>
                    )
                  )}
                </div>
              ) : (
                // Radio group for single correct answer (existing code)
                <RadioGroup
                  value={formData.correctOptions[0].toString()}
                  onValueChange={(value) =>
                    setFormData({
                      ...formData,
                      correctOptions: [Number.parseInt(value)],
                    })
                  }
                  className="space-y-4"
                >
                  {Array.from({ length: options.numberOfOptions }).map(
                    (_, index) => (
                      <div key={index} className="flex items-start gap-4">
                        <div className="flex items-center h-10 mt-2">
                          <RadioGroupItem
                            value={index.toString()}
                            id={`option-${index}`}
                          />
                          <Label
                            htmlFor={`option-${index}`}
                            className="ml-2 text-xs"
                          >
                            {options.questionType === 'true-false'
                              ? index === 0
                                ? 'True'
                                : 'False'
                              : 'Select Correct Option'}
                          </Label>
                        </div>
                        <div className="flex-1">
                          <div className="border border-border rounded-md">
                            <div className="flex items-center p-2 border-b border-border">
                              {/* Simplified toolbar */}
                              <div className="flex gap-1">
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="icon"
                                  className="h-8 w-8"
                                >
                                  <span className="font-bold">B</span>
                                </Button>
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="icon"
                                  className="h-8 w-8"
                                >
                                  <span className="italic">I</span>
                                </Button>
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="icon"
                                  className="h-8 w-8"
                                >
                                  <span className="underline">U</span>
                                </Button>
                              </div>
                            </div>
                            <Textarea
                              value={
                                options.questionType === 'true-false'
                                  ? index === 0
                                    ? 'True'
                                    : 'False'
                                  : formData.options[index]
                              }
                              onChange={(e) =>
                                handleOptionChange(index, e.target.value)
                              }
                              placeholder={`Enter option ${index + 1}`}
                              className="min-h-[80px] border-0 focus-visible:ring-0 focus-visible:ring-offset-0"
                              readOnly={options.questionType === 'true-false'}
                            />
                          </div>
                        </div>
                      </div>
                    )
                  )}
                </RadioGroup>
              )}
            </div>
          )}

          <div className="space-y-2">
            <label
              htmlFor="explanation"
              className="text-sm font-medium text-foreground"
            >
              Answer Explanation{' '}
              {['short-answer', 'essay'].includes(options.questionType) && (
                <span className="text-red-500">*</span>
              )}
            </label>
            <div className="border border-border rounded-md">
              <div className="flex items-center p-2 border-b border-border">
                {/* Simplified toolbar */}
                <div className="flex gap-1">
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8"
                  >
                    <span className="font-bold">B</span>
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8"
                  >
                    <span className="italic">I</span>
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8"
                  >
                    <span className="underline">U</span>
                  </Button>
                </div>
              </div>
              <Textarea
                id="explanation"
                value={formData.explanation}
                onChange={(e) =>
                  setFormData({ ...formData, explanation: e.target.value })
                }
                placeholder={`Enter explanation for the correct answer${
                  ['short-answer', 'essay'].includes(options.questionType)
                    ? ' (required)'
                    : ' (optional)'
                }...`}
                className="min-h-[100px] border-0 focus-visible:ring-0 focus-visible:ring-offset-0"
                required={['short-answer', 'essay'].includes(
                  options.questionType
                )}
              />
            </div>
          </div>

          <div className="flex justify-start pt-4">
            <Button type="submit" className="px-8">
              Submit
            </Button>
          </div>
        </form>
      </CardContent>
    </Card>
  );
}
