'use client';

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { Home, ChevronRight, Minus, X } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import subAdminService from '@/services/subAdminService';
import {groupService} from '@/services/api.ts';

export default function AddNewSubAdmin() {
  const navigate = useNavigate();
  const [groups, setGroups] = useState([]);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    mobile: '',
    email: '',
    password: '',
    groups: [],
  });

  // Fetch groups
  useEffect(() => {
    const fetchGroups = async () => {
      try {
        const data = await groupService.getAllGroups();
        setGroups(data);
      } catch (error) {
        console.error('Error fetching groups:', error);
        toast.error('Failed to fetch groups');
      }
    };

    fetchGroups();
  }, []);

  const handleGroupChange = (groupId, checked) => {
    if (checked) {
      setFormData({
        ...formData,
        groups: [...formData.groups, groupId],
      });
    } else {
      setFormData({
        ...formData,
        groups: formData.groups.filter((g) => g !== groupId),
      });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Validate form data
      if (!formData.firstName || !formData.lastName || !formData.mobile || !formData.email || !formData.password) {
        toast.error('Please fill in all required fields');
        return;
      }

      // Validate email format
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(formData.email)) {
        toast.error('Please enter a valid email address');
        return;
      }

      // Validate mobile number format (10 digits)
      const mobileRegex = /^[0-9]{10}$/;
      if (!mobileRegex.test(formData.mobile)) {
        toast.error('Please enter a valid 10-digit mobile number');
        return;
      }

      // Validate password (minimum 6 characters)
      if (formData.password.length < 6) {
        toast.error('Password must be at least 6 characters long');
        return;
      }

      await subAdminService.createSubAdmin(formData);
      toast.success('Sub-admin created successfully');
      navigate('/admin/sub-admins');
    } catch (error) {
      console.error('Error creating sub-admin:', error);
      toast.error(error.response?.data?.message || 'Failed to create sub-admin');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="">
      {/* Main Card */}
      <Card className="">
        <CardHeader className="flex flex-row items-center justify-between border-b border-gray-200 py-3 px-4">
          <CardTitle className="text-lg font-medium">
            Add new sub admin
          </CardTitle>
        </CardHeader>
        <CardContent className="p-6">
          <form onSubmit={handleSubmit}>
            <div className="grid gap-6">
              {/* First Name */}
              <div className="space-y-2">
                <Label htmlFor="firstName">First Name *</Label>
                <Input
                  id="firstName"
                  placeholder="Enter First name"
                  value={formData.firstName}
                  onChange={(e) =>
                    setFormData({ ...formData, firstName: e.target.value })
                  }
                  required
                />
              </div>

              {/* Last Name */}
              <div className="space-y-2">
                <Label htmlFor="lastName">Last Name *</Label>
                <Input
                  id="lastName"
                  placeholder="Enter Last name"
                  value={formData.lastName}
                  onChange={(e) =>
                    setFormData({ ...formData, lastName: e.target.value })
                  }
                  required
                />
              </div>

              {/* Mobile Number */}
              <div className="space-y-2">
                <Label htmlFor="mobileNumber">Mobile Number *</Label>
                <Input
                  id="mobileNumber"
                  placeholder="Enter mobile number"
                  value={formData.mobile}
                  onChange={(e) =>
                    setFormData({ ...formData, mobile: e.target.value })
                  }
                  required
                />
              </div>

              {/* Email */}
              <div className="space-y-2">
                <Label htmlFor="email">Email *</Label>
                <Input
                  id="email"
                  type="email"
                  placeholder="Enter email"
                  value={formData.email}
                  onChange={(e) =>
                    setFormData({ ...formData, email: e.target.value })
                  }
                  required
                />
              </div>

              {/* Password */}
              <div className="space-y-2">
                <Label htmlFor="password">Password *</Label>
                <Input
                  id="password"
                  type="password"
                  placeholder="Enter Password"
                  value={formData.password}
                  onChange={(e) =>
                    setFormData({ ...formData, password: e.target.value })
                  }
                  required
                />
              </div>

              {/* Groups Selection */}
              <div className="space-y-3">
                <Label>Select Groups for this sub admin</Label>
                <div className="grid gap-2">
                  {groups.map((group) => (
                    <div key={group._id} className="flex items-center space-x-2">
                      <Checkbox
                        id={group._id}
                        checked={formData.groups.includes(group._id)}
                        onCheckedChange={(checked) =>
                          handleGroupChange(group._id, checked)
                        }
                      />
                      <Label
                        htmlFor={group._id}
                        className="text-sm font-normal cursor-pointer"
                      >
                        {group.name}
                      </Label>
                    </div>
                  ))}
                </div>
              </div>

              {/* Submit Button */}
              <div>
                <Button
                  type="submit"
                  className="bg-green-600 hover:bg-green-700 text-white"
                  disabled={loading}
                >
                  {loading ? 'Creating...' : 'Add new Sub Admin'}
                </Button>
              </div>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}
