'use client';

import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Checkbox } from '@/components/ui/checkbox';
import { paperService, questionService, type Question, type Paper } from '@/services/api.ts';
import React from 'react';
import { Trash2, ArrowUpDown } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { categoryService, type Category } from '@/services/api.ts';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Loading } from '@/components/ui/loading';

interface PaperWithQuestions extends Omit<Paper, 'questions'> {
  questions: Array<string | Question>;
}

interface QuestionWithId {
  _id: string;
}

export function AddQuestionsToPaper() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [paper, setPaper] = useState<PaperWithQuestions | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [selectedQuestions, setSelectedQuestions] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    category: 'all',
    subCategory: 'all',
    level: 'all',
    questionType: 'all',
  });
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [sortConfig, setSortConfig] = useState<{
    key: string;
    direction: 'asc' | 'desc';
  } | null>(null);

  useEffect(() => {
    loadData();
  }, [id]);

  const loadData = async () => {
    try {
      setLoading(true);
      const [paperData, questionsData, categoriesData] = await Promise.all([
        paperService.getPaperById(id!),
        questionService.getAllQuestions(),
        categoryService.getAllCategories()
      ]);
      setPaper(paperData as PaperWithQuestions);
      setQuestions(questionsData);
      setCategories(categoriesData);

      // Pre-select questions that are already in the paper
      if (paperData.questions && Array.isArray(paperData.questions)) {
        const existingQuestionIds = paperData.questions.map(q =>
          typeof q === 'string' ? q : (q as QuestionWithId)._id
        );
        setSelectedQuestions(existingQuestionIds);
      }
    } catch (error: any) {
      toast.error(error.message || 'Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  // Helper function to get category name by ID
  const getCategoryName = (categoryId: string) => {
    const category = categories.find(cat => cat._id === categoryId);
    return category?.name || categoryId;
  };

  // Helper function to get subcategory name by ID
  const getSubCategoryName = (mainCategoryId: string, subCategoryId: string) => {
    const category = categories.find(cat => cat._id === mainCategoryId);
    const subCategory = category?.subCategories.find(sub => sub._id === subCategoryId);
    return subCategory?.name || subCategoryId;
  };

  // Helper function to get level badge color
  const getLevelBadgeColor = (level: string) => {
    switch (level) {
      case 'top-simple':
        return 'bg-green-100 text-green-700 hover:bg-green-200';
      case 'top-medium':
        return 'bg-yellow-100 text-yellow-700 hover:bg-yellow-200';
      case 'top-hard':
        return 'bg-red-100 text-red-700 hover:bg-red-200';
      default:
        return 'bg-gray-100 text-gray-700 hover:bg-gray-200';
    }
  };

  const handleQuestionToggle = (questionId: string) => {
    // Don't allow toggling if question is already in paper
    if (paper?.questions?.some(q => 
      (typeof q === 'string' ? q : q._id) === questionId
    )) {
      return;
    }
    
    setSelectedQuestions(prev => {
      if (prev.includes(questionId)) {
        return prev.filter(id => id !== questionId);
      } else {
        return [...prev, questionId];
      }
    });
  };

  const handleDeleteQuestion = async (questionId: string) => {
    if (window.confirm('Are you sure you want to remove this question from the paper?')) {
      try {
        // Remove from selected questions if it's there
        setSelectedQuestions(prev => prev.filter(id => id !== questionId));
        
        // Update the paper by removing the question
        const updatedQuestions = paper?.questions
          ?.filter(q => (typeof q === 'string' ? q : q._id) !== questionId)
          .map(q => typeof q === 'string' ? q : q._id) || [];
        
        await paperService.updatePaper(id!, { questions: updatedQuestions });
        
        // Refresh the paper data
        const updatedPaper = await paperService.getPaperById(id!);
        setPaper(updatedPaper as PaperWithQuestions);
        
        toast.success('Question removed from paper successfully');
      } catch (error: any) {
        toast.error(error.message || 'Failed to remove question from paper');
      }
    }
  };

  const handleSubmit = async () => {
    try {
      // Only add new questions that aren't already in the paper
      const newQuestions = selectedQuestions.filter(
        questionId => !paper?.questions?.some(q => 
          (typeof q === 'string' ? q : q._id) === questionId
        )
      );
      
      if (newQuestions.length > 0) {
        await paperService.addQuestionsToPaper(id!, newQuestions);
        toast.success('Questions added successfully');
      }
      navigate('/admin/all-papers');
    } catch (error: any) {
      toast.error(error.message || 'Failed to update questions');
    }
  };

  const handleSort = (key: string) => {
    setSortConfig((current) => {
      if (current?.key === key) {
        return {
          key,
          direction: current.direction === 'asc' ? 'desc' : 'asc',
        };
      }
      return { key, direction: 'asc' };
    });
  };

  const getFilteredAndSortedQuestions = () => {
    let filtered = [...questions];

    // Apply search filter
    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      filtered = filtered.filter(q => 
        q.questionText.toLowerCase().includes(term) ||
        q.questionType.toLowerCase().includes(term) ||
        getCategoryName(q.mainCategory).toLowerCase().includes(term) ||
        getSubCategoryName(q.mainCategory, q.subCategory).toLowerCase().includes(term) ||
        q.level.toLowerCase().includes(term)
      );
    }

    // Apply filters
    if (filters.category && filters.category !== 'all') {
      filtered = filtered.filter(q => q.mainCategory === filters.category);
    }
    if (filters.subCategory && filters.subCategory !== 'all') {
      filtered = filtered.filter(q => q.subCategory === filters.subCategory);
    }
    if (filters.level && filters.level !== 'all') {
      filtered = filtered.filter(q => q.level === filters.level);
    }
    if (filters.questionType && filters.questionType !== 'all') {
      filtered = filtered.filter(q => q.questionType === filters.questionType);
    }

    // Apply sorting
    if (sortConfig) {
      filtered.sort((a, b) => {
        const aValue = a[sortConfig.key as keyof Question];
        const bValue = b[sortConfig.key as keyof Question];
        
        if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }

    return filtered;
  };

  const filteredQuestions = getFilteredAndSortedQuestions();
  const totalPages = Math.ceil(filteredQuestions.length / pageSize);
  const startIndex = (currentPage - 1) * pageSize;
  const paginatedQuestions = filteredQuestions.slice(startIndex, startIndex + pageSize);

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Add Questions to Paper: {paper?.name || 'Loading...'}</CardTitle>
        </CardHeader>
        <CardContent>
          <Loading text="Loading questions and paper data..." />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Add Questions to Paper: {paper?.name}</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <div className="text-sm text-muted-foreground">
              Selected Questions: {selectedQuestions.length}
            </div>
            <Button onClick={handleSubmit}>Save Changes</Button>
          </div>

          {/* Search and Page Size Controls */}
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-2">
              <div className="text-sm">Show</div>
              <Select
                value={pageSize.toString()}
                onValueChange={(value) => {
                  setPageSize(Number(value));
                  setCurrentPage(1);
                }}
              >
                <SelectTrigger className="h-8 w-[70px]">
                  <SelectValue placeholder={pageSize} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="5">5</SelectItem>
                  <SelectItem value="10">10</SelectItem>
                  <SelectItem value="20">20</SelectItem>
                  <SelectItem value="50">50</SelectItem>
                </SelectContent>
              </Select>
              <div className="text-sm">entries</div>
            </div>
            <div className="flex items-center gap-2">
              <div className="text-sm">Search:</div>
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => {
                  setSearchTerm(e.target.value);
                  setCurrentPage(1);
                }}
                placeholder="Search questions..."
                className="h-8 px-3 border rounded-md"
              />
            </div>
          </div>

          {/* Filters */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Category</label>
              <Select
                value={filters.category}
                onValueChange={(value) => setFilters(prev => ({ ...prev, category: value }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="All Categories" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Categories</SelectItem>
                  {categories.map((category) => (
                    <SelectItem key={category._id} value={category._id}>
                      {category.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Sub Category</label>
              <Select
                value={filters.subCategory}
                onValueChange={(value) => setFilters(prev => ({ ...prev, subCategory: value }))}
                disabled={!filters.category || filters.category === 'all'}
              >
                <SelectTrigger>
                  <SelectValue placeholder="All Sub Categories" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Sub Categories</SelectItem>
                  {categories
                    .find(cat => cat._id === filters.category)
                    ?.subCategories.map((sub) => (
                      <SelectItem key={sub._id} value={sub._id}>
                        {sub.name}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Level</label>
              <Select
                value={filters.level}
                onValueChange={(value) => setFilters(prev => ({ ...prev, level: value }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="All Levels" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Levels</SelectItem>
                  <SelectItem value="top-simple">Simple</SelectItem>
                  <SelectItem value="top-medium">Medium</SelectItem>
                  <SelectItem value="top-hard">Hard</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Question Type</label>
              <Select
                value={filters.questionType}
                onValueChange={(value) => setFilters(prev => ({ ...prev, questionType: value }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="All Types" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Types</SelectItem>
                  <SelectItem value="multiple-choice">Multiple Choice</SelectItem>
                  <SelectItem value="true-false">True/False</SelectItem>
                  <SelectItem value="short-answer">Short Answer</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-[50px]">Select</TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    onClick={() => handleSort('questionText')}
                    className="flex items-center gap-2"
                  >
                    Question
                    <ArrowUpDown className="h-4 w-4" />
                    {sortConfig?.key === 'questionText' && (
                      <span>{sortConfig.direction === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </Button>
                </TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    onClick={() => handleSort('questionType')}
                    className="flex items-center gap-2"
                  >
                    Type
                    <ArrowUpDown className="h-4 w-4" />
                    {sortConfig?.key === 'questionType' && (
                      <span>{sortConfig.direction === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </Button>
                </TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    onClick={() => handleSort('mainCategory')}
                    className="flex items-center gap-2"
                  >
                    Category
                    <ArrowUpDown className="h-4 w-4" />
                    {sortConfig?.key === 'mainCategory' && (
                      <span>{sortConfig.direction === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </Button>
                </TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    onClick={() => handleSort('subCategory')}
                    className="flex items-center gap-2"
                  >
                    Sub Category
                    <ArrowUpDown className="h-4 w-4" />
                    {sortConfig?.key === 'subCategory' && (
                      <span>{sortConfig.direction === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </Button>
                </TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    onClick={() => handleSort('level')}
                    className="flex items-center gap-2"
                  >
                    Level
                    <ArrowUpDown className="h-4 w-4" />
                    {sortConfig?.key === 'level' && (
                      <span>{sortConfig.direction === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </Button>
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {paginatedQuestions.map((question) => (
                <TableRow
                  key={question._id}
                  className={paper?.questions?.some(q => 
                    (typeof q === 'string' ? q : q._id) === question._id
                  ) ? 'bg-muted/50' : ''}
                >
                  <TableCell>
                    {paper?.questions?.some(q => 
                      (typeof q === 'string' ? q : q._id) === question._id
                    ) ? (
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 text-red-500 hover:text-red-600"
                        onClick={() => handleDeleteQuestion(question._id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    ) : (
                      <Checkbox
                        checked={selectedQuestions.includes(question._id)}
                        onCheckedChange={() => handleQuestionToggle(question._id)}
                      />
                    )}
                  </TableCell>
                  <TableCell className="max-w-[500px] truncate">
                    <div className="flex items-center gap-2">
                      {question.questionText}
                      {paper?.questions?.some(q => 
                        (typeof q === 'string' ? q : q._id) === question._id
                      ) && (
                        <span className="text-xs text-muted-foreground">(Already in paper)</span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className="capitalize">
                      {question.questionType}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant="secondary" className="capitalize">
                      {getCategoryName(question.mainCategory)}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant="secondary" className="capitalize">
                      {getSubCategoryName(question.mainCategory, question.subCategory)}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge className={`capitalize ${getLevelBadgeColor(question.level)}`}>
                      {question.level.replace('top-', '')}
                    </Badge>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>

          {/* Pagination */}
          <div className="flex items-center justify-between">
            <div className="text-sm text-muted-foreground">
              Showing {startIndex + 1} to {Math.min(startIndex + pageSize, filteredQuestions.length)} of {filteredQuestions.length} entries
            </div>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
                disabled={currentPage === 1}
              >
                Previous
              </Button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                <Button
                  key={page}
                  variant={currentPage === page ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setCurrentPage(page)}
                >
                  {page}
                </Button>
              ))}
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
                disabled={currentPage === totalPages}
              >
                Next
              </Button>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

export default AddQuestionsToPaper; 