import React from 'react';
import { useForm } from 'react-hook-form';
import { toast } from 'react-toastify';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import {
  type Question,
  type Category,
  questionService,
} from '@/services/api.ts';
import { Loading } from '@/components/ui/loading';
import { Plus, Trash2 } from 'lucide-react';

interface EditQuestionProps {
  question: Question | null;
  categories: Category[];
  isOpen: boolean;
  onClose: () => void;
  onUpdate: () => void;
}

interface Option {
  text: string;
  isCorrect: boolean;
}

export function EditQuestion({
  question,
  categories,
  isOpen,
  onClose,
  onUpdate,
}: EditQuestionProps) {
  const [loading, setLoading] = React.useState(false);
  const [questionData, setQuestionData] = React.useState<Question | null>(null);
  const [options, setOptions] = React.useState<Option[]>([]);
  const [formData, setFormData] = React.useState<Partial<Question>>({
    questionText: '',
    answer: '',
    mainCategory: '',
    subCategory: '',
    level: 'top-simple',
    status: 'Active',
    questionType: 'multiple-choice-single',
    options: [],
    marks: 1,
    explanation: '',
  });

  const form = useForm({
    defaultValues: {
      questionText: '',
      answer: '',
      mainCategory: '',
      subCategory: '',
      level: 'top-simple',
      status: 'Active',
      questionType: 'multiple-choice-single',
      marks: 1,
      explanation: '',
    },
  });

  const [selectedMainCategory, setSelectedMainCategory] = React.useState('');
  const questionType = formData.questionType;

  // Reset form when dialog opens/closes
  React.useEffect(() => {
    if (!isOpen) {
      setFormData({
        questionText: '',
        answer: '',
        mainCategory: '',
        subCategory: '',
        level: 'top-simple',
        status: 'Active',
        questionType: 'multiple-choice-single',
        options: [],
        marks: 1,
        explanation: '',
      });
      setOptions([]);
      setSelectedMainCategory('');
    }
  }, [isOpen]);

  // Fetch question data when dialog opens
  React.useEffect(() => {
    if (question) {
      fetchQuestionData();
    }
  }, [question]);

  const fetchQuestionData = async () => {
    try {
      setLoading(true);
      const questionData = await questionService.getQuestion(question._id);
      setFormData({
        ...questionData,
        answer: questionData.answer || '',
        explanation: questionData.explanation || '',
      });
      setSelectedMainCategory(questionData.mainCategory);
      form.reset({
        questionText: questionData.questionText,
        answer: questionData.answer || '',
        mainCategory: questionData.mainCategory,
        subCategory: questionData.subCategory,
        level: questionData.level,
        status: questionData.status,
        questionType: questionData.questionType,
        marks: questionData.marks,
        explanation: questionData.explanation || '',
      });
    } catch (error: any) {
      toast.error(error.message || 'Failed to fetch question data');
    } finally {
      setLoading(false);
    }
  };

  const onSubmit = async (data: any) => {
    try {
      setLoading(true);

      // Validate explanation for short-answer and essay questions
      if (
        ['short-answer', 'essay'].includes(data.questionType) &&
        !data.explanation?.trim()
      ) {
        toast.error(
          'Explanation is required for short-answer and essay questions'
        );
        return;
      }

      const updateData = {
        ...data,
        options: [
          'multiple-choice-single',
          'multiple-choice-multiple',
          'true-false',
        ].includes(data.questionType)
          ? data.questionType === 'true-false'
            ? [
                { text: 'True', isCorrect: data.answer === 'True' },
                { text: 'False', isCorrect: data.answer === 'False' },
              ]
            : data.questionType === 'multiple-choice-single'
            ? options.map((opt) => ({
                ...opt,
                isCorrect:
                  opt.isCorrect &&
                  options.findIndex((o) => o.isCorrect) ===
                    options.indexOf(opt),
              })) // Keep all options but only one can be correct
            : options // Keep all options for multiple-choice-multiple
          : undefined,
        answer: ['true-false', 'short-answer'].includes(data.questionType)
          ? data.answer
          : undefined,
      };

      await questionService.updateQuestion(question._id!, updateData);
      toast.success('Question updated successfully');
      onUpdate();
      onClose();
    } catch (error: any) {
      toast.error(error.message || 'Failed to update question');
    } finally {
      setLoading(false);
    }
  };

  const getSubCategories = (mainCategoryId: string) => {
    const category = categories.find((cat) => cat._id === mainCategoryId);
    return category?.subCategories || [];
  };

  const addOption = () => {
    setOptions([...options, { text: '', isCorrect: false }]);
  };

  const removeOption = (index: number) => {
    setOptions(options.filter((_, i) => i !== index));
  };

  const updateOption = (index: number, field: keyof Option, value: any) => {
    const newOptions = [...options];
    newOptions[index] = { ...newOptions[index], [field]: value };
    setOptions(newOptions);
  };

  if (loading) {
    return (
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle>Edit Question</DialogTitle>
          </DialogHeader>
          <div className="flex items-center justify-center py-8">
            <Loading text="Loading question data..." />
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-auto">
        <DialogHeader>
          <DialogTitle>Edit Question</DialogTitle>
        </DialogHeader>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="questionText"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Question Text</FormLabel>
                  <FormControl>
                    <Textarea {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="questionType"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Question Type</FormLabel>
                  <Select value={field.value} onValueChange={field.onChange}>
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder="Select question type" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      <SelectItem value="multiple-choice-single">
                        Multiple Choice Single Answer
                      </SelectItem>
                      <SelectItem value="multiple-choice-multiple">
                        Multiple Choice Multiple Answers
                      </SelectItem>
                      <SelectItem value="true-false">True/False</SelectItem>
                      <SelectItem value="short-answer">Short Answer</SelectItem>
                      <SelectItem value="essay">Essay</SelectItem>
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            {['multiple-choice-single', 'multiple-choice-multiple'].includes(
              questionType
            ) ? (
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <FormLabel>Options</FormLabel>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={addOption}
                  >
                    <Plus className="h-4 w-4 mr-2" />
                    Add Option
                  </Button>
                </div>
                {options.map((option, index) => (
                  <div key={index} className="flex items-center gap-2">
                    <Input
                      value={option.text}
                      onChange={(e) =>
                        updateOption(index, 'text', e.target.value)
                      }
                      placeholder={`Option ${index + 1}`}
                      className="flex-1"
                    />
                    <div className="flex items-center gap-2">
                      {questionType === 'multiple-choice-single' ? (
                        <label className="flex items-center gap-1">
                          <input
                            type="radio"
                            name="correctOption"
                            checked={option.isCorrect}
                            onChange={() => {
                              const newOptions = options.map((opt, i) => ({
                                ...opt,
                                isCorrect: i === index,
                              }));
                              setOptions(newOptions);
                            }}
                            className="rounded-full border-gray-300"
                          />
                          Correct
                        </label>
                      ) : (
                        <label className="flex items-center gap-1">
                          <input
                            type="checkbox"
                            checked={option.isCorrect}
                            onChange={(e) =>
                              updateOption(index, 'isCorrect', e.target.checked)
                            }
                            className="rounded border-gray-300"
                          />
                          Correct
                        </label>
                      )}
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        onClick={() => removeOption(index)}
                      >
                        <Trash2 className="h-4 w-4 text-red-500" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="space-y-4">
                <FormField
                  control={form.control}
                  name="answer"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Answer</FormLabel>
                      <FormControl>
                        {questionType === 'true-false' ? (
                          <Select
                            value={field.value}
                            onValueChange={field.onChange}
                            defaultValue={field.value}
                          >
                            <FormControl>
                              <SelectTrigger>
                                <SelectValue placeholder="Select answer" />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                              <SelectItem value="True">True</SelectItem>
                              <SelectItem value="False">False</SelectItem>
                            </SelectContent>
                          </Select>
                        ) : (
                          <Textarea
                            {...field}
                            value={field.value || ''}
                            placeholder={`Enter ${
                              questionType === 'short-answer'
                                ? 'short answer'
                                : 'essay answer'
                            }...`}
                            className="min-h-[100px]"
                          />
                        )}
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>
            )}

            <div className="space-y-2">
              <label
                htmlFor="explanation"
                className="text-sm font-medium text-foreground"
              >
                Answer Explanation{' '}
                {['short-answer', 'essay'].includes(questionType) && (
                  <span className="text-red-500">*</span>
                )}
              </label>
              <div className="border border-border rounded-md">
                <div className="flex items-center p-2 border-b border-border">
                  {/* Simplified toolbar */}
                  <div className="flex gap-1">
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8"
                    >
                      <span className="font-bold">B</span>
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8"
                    >
                      <span className="italic">I</span>
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8"
                    >
                      <span className="underline">U</span>
                    </Button>
                  </div>
                </div>
                <Textarea
                  id="explanation"
                  value={formData.explanation || ''}
                  onChange={(e) =>
                    setFormData({ ...formData, explanation: e.target.value })
                  }
                  placeholder={`Enter explanation for the correct answer${
                    ['short-answer', 'essay'].includes(questionType)
                      ? ' (required)'
                      : ' (optional)'
                  }...`}
                  className="min-h-[100px] border-0 focus-visible:ring-0 focus-visible:ring-offset-0"
                  required={['short-answer', 'essay'].includes(questionType)}
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="mainCategory"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Main Category</FormLabel>
                    <Select
                      value={field.value}
                      onValueChange={(value) => {
                        field.onChange(value);
                        setSelectedMainCategory(value);
                        setFormData({ ...formData, subCategory: '' });
                      }}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select category" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {categories.map((category) => (
                          <SelectItem key={category._id} value={category._id}>
                            {category.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="subCategory"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Sub Category</FormLabel>
                    <Select
                      value={field.value}
                      onValueChange={field.onChange}
                      disabled={!selectedMainCategory}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select subcategory" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {getSubCategories(selectedMainCategory).map(
                          (subCategory) => (
                            <SelectItem
                              key={subCategory._id}
                              value={subCategory._id}
                            >
                              {subCategory.name}
                            </SelectItem>
                          )
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="level"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Level</FormLabel>
                    <Select
                      value={field.value}
                      onValueChange={field.onChange}
                      defaultValue={field.value}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select level" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="top-simple">Simple</SelectItem>
                        <SelectItem value="top-medium">Medium</SelectItem>
                        <SelectItem value="top-hard">Hard</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="status"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Status</FormLabel>
                    <Select value={field.value} onValueChange={field.onChange}>
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select status" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="Active">Active</SelectItem>
                        <SelectItem value="Inactive">Inactive</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="marks"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Marks</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        min={1}
                        {...field}
                        onChange={(e) => field.onChange(Number(e.target.value))}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <div className="flex justify-end space-x-2">
              <Button variant="outline" type="button" onClick={onClose}>
                Cancel
              </Button>
              <Button type="submit">Save Changes</Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}
