'use client';
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  type ColumnDef,
  type ColumnFiltersState,
  type SortingState,
  type VisibilityState,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table';
import { ArrowUpDown, Edit, Eye, Share, Trash } from 'lucide-react';
import { toast } from 'react-toastify';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { paperService, type Paper } from '@/services/api.ts';
import { Loading } from '@/components/ui/loading';
import { Card, CardContent } from '@/components/ui/card';

export function PaperDataTable() {
  const navigate = useNavigate();
  const [data, setData] = useState<Paper[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sorting, setSorting] = useState<SortingState>([]);
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({});
  const [rowSelection, setRowSelection] = useState({});
  const [pageSize, setPageSize] = useState(10);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadPapers();
  }, []);

  const loadPapers = async () => {
    try {
      setLoading(true);
      setError(null);
      const papers = await paperService.getAllPapers();
      setData(papers);
    } catch (error: any) {
      setError(error.message || 'Failed to load papers');
      toast.error('Failed to load papers');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this paper?')) {
      try {
        await paperService.deletePaper(id);
        toast.success('Paper deleted successfully');
        loadPapers(); // Reload the papers list
      } catch (error: any) {
        toast.error(error.message || 'Failed to delete paper');
      }
    }
  };

  const handleShare = (id: string) => {
    // Implement share logic here
    console.log('Sharing paper with id:', id);
  };

  const handleStatusToggle = async (id: string, currentStatus: string) => {
    try {
      const newStatus = currentStatus === 'Active' ? 'Deactive' : 'Active';
      await paperService.updatePaperStatus(id, newStatus);
      toast.success(`Paper status updated to ${newStatus}`);
      loadPapers(); // Reload the papers list
    } catch (error: any) {
      toast.error(error.message || 'Failed to update paper status');
    }
  };

  const columns: ColumnDef<Paper>[] = [
    {
      accessorKey: 'id',
      header: 'Sr No.',
      cell: ({ row }) => <div>{row.index + 1}</div>,
    },
    {
      accessorKey: 'name',
      header: ({ column }) => {
        return (
          <Button
            variant="ghost"
            onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
          >
            Name
            <ArrowUpDown className="ml-2 h-4 w-4" />
          </Button>
        )
      },
    },
    {
      accessorKey: 'startDate',
      header: ({ column }) => {
        return (
          <Button
            variant="ghost"
            onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
          >
            Start Date
            <ArrowUpDown className="ml-2 h-4 w-4" />
          </Button>
        )
      },
      cell: ({ row }) => {
        const date = new Date(row.getValue('startDate'));
        return date.toLocaleDateString('en-GB');
      },
    },
    {
      accessorKey: 'endDate',
      header: ({ column }) => {
        return (
          <Button
            variant="ghost"
            onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
          >
            End Date
            <ArrowUpDown className="ml-2 h-4 w-4" />
          </Button>
        )
      },
      cell: ({ row }) => {
        const date = new Date(row.getValue('endDate'));
        return date.toLocaleDateString('en-GB');
      },
    },
    {
      accessorKey: 'totalQuestions',
      header: ({ column }) => {
        return (
          <Button
            variant="ghost"
            onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
          >
            Total Questions
            <ArrowUpDown className="ml-2 h-4 w-4" />
          </Button>
        )
      },
      cell: ({ row }) => {
        const count = row.getValue('totalQuestions') as number;
        return count || 0;
      },
    },
    {
      accessorKey: 'duration',
      header: ({ column }) => {
        return (
          <Button
            variant="ghost"
            onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
          >
            Duration (minutes)
            <ArrowUpDown className="ml-2 h-4 w-4" />
          </Button>
        )
      },
    },
    {
      accessorKey: 'questionAddMethod',
      header: ({ column }) => {
        return (
          <Button
            variant="ghost"
            onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
          >
            Question Mode
            <ArrowUpDown className="ml-2 h-4 w-4" />
          </Button>
        )
      },
    },
    {
      accessorKey: 'status',
      header: 'Status',
      cell: ({ row }) => {
        const paper = row.original;
        const status = paper.status as string;
        return (
          <div className="flex items-center gap-2">
            <div
              className={`rounded px-2 py-1 text-center text-xs font-medium ${
                status === 'Active' 
                  ? 'bg-green-100 text-green-700 hover:bg-green-200' 
                  : 'bg-red-100 text-red-700 hover:bg-red-200'
              }`}
            >
              {status}
            </div>
            
          </div>
        );
      },
    },
    {
      id: 'actions',
      header: 'Actions',
      cell: ({ row }) => {
        const paper = row.original;
        return (
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 bg-blue-100 text-blue-500 hover:bg-blue-200 hover:text-blue-600"
              onClick={() => navigate(`/admin/papers/${paper._id}/add-questions`)}
            >
              <Eye className="h-4 w-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 bg-green-100 text-green-500 hover:bg-green-200 hover:text-green-600"
              onClick={() => navigate(`/admin/papers/${paper._id}/edit`)}
            >
              <Edit className="h-4 w-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 bg-red-100 text-red-500 hover:bg-red-200 hover:text-red-600"
              onClick={() => handleDelete(paper._id)}
            >
              <Trash className="h-4 w-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className={`h-8 w-8 ${
                paper.status === 'Active'
                  ? 'bg-green-100 text-green-500 hover:bg-green-200 hover:text-green-600'
                  : 'bg-red-100 text-red-500 hover:bg-red-200 hover:text-red-600'
              }`}
              onClick={() => handleStatusToggle(paper._id, paper.status)}
            >
              {paper.status === 'Active' ? '✓' : '✕'}
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 bg-orange-100 text-orange-500 hover:bg-orange-200 hover:text-orange-600"
              onClick={() => handleShare(paper._id)}
            >
              <Share className="h-4 w-4" />
            </Button>
          </div>
        );
      },
    },
  ];

  const filteredData = React.useMemo(() => {
    if (!searchTerm) return data;
    
    const term = searchTerm.toLowerCase();
    return data.filter(paper => 
      paper.name.toLowerCase().includes(term) ||
      paper.questionAddMethod.toLowerCase().includes(term)
    );
  }, [data, searchTerm]);

  const table = useReactTable({
    data: filteredData,
    columns,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    state: {
      sorting,
      columnFilters,
      columnVisibility,
      rowSelection,
    },
  });

  if (loading) {
    return (
      <Card>
        <CardContent className="p-0">
          <div className="flex items-center justify-between p-4 border-b">
            <div className="flex items-center">
              <h1 className="text-2xl font-bold text-foreground">
                All Papers List
                <div className="text-sm font-[400] text-muted-foreground">
                  All papers included in this List.
                </div>
              </h1>
            </div>
          </div>
          <Loading text="Loading papers..." />
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-red-500">{error}</div>
      </div>
    );
  }

  return (
    <div className="bg-background rounded-md border ">
      <div className="flex items-center justify-between p-4 border-b border-foreground">
        <div className="flex items-center gap-2">
          <div className="text-sm">Show</div>
          <Select
            value={pageSize.toString()}
            onValueChange={(value) => {
              const size = Number.parseInt(value);
              setPageSize(size);
              table.setPageSize(size);
            }}
          >
            <SelectTrigger className="h-8 w-[70px]">
              <SelectValue placeholder={pageSize} />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="10">10</SelectItem>
              <SelectItem value="20">20</SelectItem>
              <SelectItem value="30">30</SelectItem>
              <SelectItem value="40">40</SelectItem>
              <SelectItem value="50">50</SelectItem>
            </SelectContent>
          </Select>
          <div className="text-sm">entries</div>
        </div>
        <div className="flex items-center gap-2">
          <div className="text-sm">Search:</div>
          <Input
            placeholder="Search by name or question mode..."
            value={searchTerm}
            onChange={(event) => setSearchTerm(event.target.value)}
            className="h-8 w-[200px]"
          />
        </div>
      </div>
      <div className="">
        <Table className='text-center'>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  return (
                    <TableHead className='text-center' key={header.id}>
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                    </TableHead>
                  );
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && 'selected'}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext()
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className="h-24 text-center"
                >
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <div className="flex items-center justify-between p-4">
        <div className="text-sm text-muted-foreground">
          Showing{' '}
          {table.getState().pagination.pageIndex *
            table.getState().pagination.pageSize +
            1}{' '}
          to{' '}
          {Math.min(
            (table.getState().pagination.pageIndex + 1) *
              table.getState().pagination.pageSize,
            table.getFilteredRowModel().rows.length
          )}{' '}
          of {table.getFilteredRowModel().rows.length} entries
        </div>
        <div className="flex items-center space-x-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            Previous
          </Button>
          {Array.from({ length: table.getPageCount() }).map((_, index) => (
            <Button
              key={index}
              variant={
                table.getState().pagination.pageIndex === index
                  ? 'default'
                  : 'outline'
              }
              size="sm"
              onClick={() => table.setPageIndex(index)}
            >
              {index + 1}
            </Button>
          ))}
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  );
}
