'use client';

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Download, Home, ChevronDown, ChevronUp } from 'lucide-react';
import { toast } from 'react-toastify';
import * as XLSX from 'xlsx';
import { userService, groupService } from '@/services/api.ts';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Label } from '@/components/ui/label';

export default function BulkUsersUpload() {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [fileName, setFileName] = useState(null);
  const [selectedFile, setSelectedFile] = useState(null);
  const [userRole, setUserRole] = useState('');
  const [selectedGroup, setSelectedGroup] = useState('');
  const [sendEmail, setSendEmail] = useState(false);
  const [forceReset, setForceReset] = useState(false);
  const [loading, setLoading] = useState(false);
  const [groups, setGroups] = useState([]);

  useEffect(() => {
    const fetchGroups = async () => {
      try {
        const data = await groupService.getAllGroups();
        setGroups(data);
      } catch (error) {
        console.error('Error fetching groups:', error);
        toast.error('Failed to load groups');
      }
    };

    fetchGroups();
  }, []);

  const handleFileChange = (e) => {
    const file = e.target.files?.[0];
    setFileName(file ? file.name : null);
    setSelectedFile(file || null);
  };

  const handleUpload = async () => {
    if (!selectedFile || !userRole || !selectedGroup) {
      toast.error('Please select a file, user role, and group');
      return;
    }

    try {
      setLoading(true);
      const reader = new FileReader();
      reader.onload = async (e) => {
        try {
          const data = e.target?.result;
          const workbook = XLSX.read(data, { type: 'binary' });
          const sheetName = workbook.SheetNames[0];
          const worksheet = workbook.Sheets[sheetName];
          const jsonData = XLSX.utils.sheet_to_json(worksheet);

          const users = jsonData.map((row) => ({
            name: row.name,
            email: row.email,
            mobile: row.mobile,
            group: selectedGroup, // Use the selected group ID
            role: userRole,
            password: row.password || Math.random().toString(36).slice(-8),
            sendEmail,
            forceReset,
          }));

          await userService.bulkCreateUsers(users);
          toast.success('Users uploaded successfully');
          setFileName(null);
          setSelectedFile(null);
        } catch (error) {
          toast.error('Error processing file');
          console.error('Error processing file:', error);
        }
      };
      reader.readAsBinaryString(selectedFile);
    } catch (error) {
      toast.error('Error uploading file');
      console.error('Error uploading file:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadSample = () => {
    const sampleData = [
      {
        name: 'John Doe',
        email: 'john.doe@example.com',
        mobile: '1234567890',
        password: 'optional_password'
      }
    ];

    const ws = XLSX.utils.json_to_sheet(sampleData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Users');
    XLSX.writeFile(wb, 'sample_users.xlsx');
  };

  return (
    <div className="container mx-auto p-4">
      <div className="flex flex-col space-y-4">
        {/* Header and Breadcrumb */}
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-4">
          <div>
            <h1 className="text-2xl font-bold text-[#5a5a5a]">
              Bulk Users Upload
            </h1>
            <p className="text-sm text-muted-foreground">
              Upload Users via Excel File
            </p>
          </div>
          <div className="flex items-center space-x-2 text-sm">
            <Link
              to="/"
              className="flex items-center text-muted-foreground hover:text-primary"
            >
              <Home className="h-4 w-4 mr-1" />
              Home
            </Link>
            <span className="text-muted-foreground">/</span>
            <Link
              to="/admin/users"
              className="text-muted-foreground hover:text-primary"
            >
              All Users
            </Link>
            <span className="text-muted-foreground">/</span>
            <span className="text-primary">Bulk Upload</span>
          </div>
        </div>

        {/* Main Card */}
        <Card className="border-t-4 border-t-primary">
          <CardHeader className="border-b px-6 py-4">
            <div className="flex justify-between items-center">
              <CardTitle className="text-lg font-medium text-[#5a5a5a]">
                Bulk upload facility
              </CardTitle>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setIsCollapsed(!isCollapsed)}
                className="h-6 w-6 p-0"
              >
                {isCollapsed ? (
                  <ChevronDown className="h-4 w-4" />
                ) : (
                  <ChevronUp className="h-4 w-4" />
                )}
              </Button>
            </div>
          </CardHeader>

          {!isCollapsed && (
            <CardContent className="p-6 space-y-6">
              <div className="space-y-2">
                <Label
                  htmlFor="user-role"
                  className="font-medium text-[#5a5a5a]"
                >
                  Select User Role
                </Label>
                <Select value={userRole} onValueChange={setUserRole}>
                  <SelectTrigger id="user-role" className="w-full">
                    <SelectValue placeholder="Select user role" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="student">Student</SelectItem>
                    <SelectItem value="teacher">Teacher</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label
                  htmlFor="user-group"
                  className="font-medium text-[#5a5a5a]"
                >
                  Select User Group
                </Label>
                <Select value={selectedGroup} onValueChange={setSelectedGroup}>
                  <SelectTrigger id="user-group" className="w-full">
                    <SelectValue placeholder="Select user group" />
                  </SelectTrigger>
                  <SelectContent>
                    {groups.map((group) => (
                      <SelectItem key={group._id} value={group._id}>
                        {group.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label
                  htmlFor="file-upload"
                  className="font-medium text-[#5a5a5a]"
                >
                  Upload File
                </Label>
                <div className="flex items-center border rounded-md overflow-hidden">
                  <label
                    htmlFor="file-upload"
                    className="bg-gray-100 text-gray-700 px-4 py-2 cursor-pointer border-r"
                  >
                    Choose File
                  </label>
                  <span className="px-3 text-sm text-gray-500 truncate">
                    {fileName || 'No file chosen'}
                  </span>
                  <input
                    type="file"
                    id="file-upload"
                    className="hidden"
                    onChange={handleFileChange}
                    accept=".xlsx,.xls,.csv"
                  />
                </div>
              </div>

              <Button 
                className="w-full md:w-auto bg-purple-600 hover:bg-purple-700 text-white"
                onClick={handleDownloadSample}
              >
                <Download className="mr-2 h-4 w-4" />
                Download Sample Excel File (For users bulk upload)
              </Button>

              <div className="space-y-2">
                <div className="flex items-center space-x-2">
                  <Checkbox 
                    id="send-email" 
                    checked={sendEmail}
                    onCheckedChange={(checked) => setSendEmail(checked)}
                  />
                  <Label
                    htmlFor="send-email"
                    className="text-sm font-normal cursor-pointer"
                  >
                    Send Email (System send an email to candidate with account
                    details)
                  </Label>
                </div>
                <div className="flex items-center space-x-2">
                  <Checkbox 
                    id="force-reset" 
                    checked={forceReset}
                    onCheckedChange={(checked) => setForceReset(checked)}
                  />
                  <Label
                    htmlFor="force-reset"
                    className="text-sm font-normal cursor-pointer"
                  >
                    Force User to Reset Password (After First Login)
                  </Label>
                </div>
              </div>

              <Button 
                className="bg-green-600 hover:bg-green-700"
                onClick={handleUpload}
                disabled={loading}
              >
                {loading ? 'Uploading...' : 'Upload Users Now'}
              </Button>
            </CardContent>
          )}
        </Card>
      </div>
    </div>
  );
}
