import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { toast } from 'react-toastify';
import { userService, statsService, paperService } from '../services/api';
import { groupService } from '../services/api.ts';

import { Link, useNavigate } from 'react-router-dom';
import { Loading } from '@/components/ui/loading';

import PieChartComp from './pieChart';
import { Label, Pie, PieChart } from 'recharts';
import { ChartContainer, ChartTooltip, ChartTooltipContent } from './ui/chart';

import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ChevronRight, Pencil, Search, Trash } from 'lucide-react';

const chartConfig = {
  visitors: {
    label: 'Results',
  },
  pass: {
    label: 'Pass',
    color: 'hsl(var(--chart-1))',
  },
  fail: {
    label: 'Fail',
    color: 'hsl(var(--chart-2))',
  },
};

const Dashboard = () => {
  const [users, setUsers] = useState([]);
  const [papers, setPapers] = useState([]);
  const [groups, setGroups] = useState([]);
  const [stats, setStats] = useState({
    users: { total: 0, byRole: {} },
    exams: { total: 0, active: 0, bySubject: {} },
    questions: { total: 0 },
    results: { total: 0 },
  });
  const [detailedStats, setDetailedStats] = useState({
    users: null,
    exams: null,
    questions: null,
    results: null,
  });
  const [isLoading, setIsLoading] = useState(true);

  const navigate = useNavigate();

  const loadDashboardData = useCallback(async () => {
    try {
      const [
        usersData,
        statsData,
        userStats,
        examStats,
        questionStats,
        passFailStats,
        papersData,
        groupsData,
      ] = await Promise.all([
        userService.getAllUsers(),
        statsService.getAllStats(),
        statsService.getUserStats(),
        statsService.getExamStats(),
        statsService.getQuestionStats(),
        statsService.getPassFailStats(),
        paperService.getAllPapers(),
        groupService.getAllGroups(),
      ]);

      setUsers(usersData);
      setStats(statsData);
      setPapers(papersData);
      setGroups(groupsData);
      setDetailedStats({
        users: userStats,
        exams: examStats,
        questions: questionStats,
        results: passFailStats,
      });
    } catch (err) {
      console.error('Error loading dashboard data:', err);
      toast.error('Error loading dashboard data');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadDashboardData();
  }, [loadDashboardData]);

  // Calculate paper attendance statistics
  const paperStats = useMemo(() => {
    if (!detailedStats.results) return { total: 0, pass: 0, fail: 0 };

    return {
      total: detailedStats.results.total,
      pass: detailedStats.results.pass,
      fail: detailedStats.results.fail,
    };
  }, [detailedStats.results]);

  const handleDeleteUser = async (userId) => {
    if (window.confirm('Are you sure you want to delete this user?')) {
      try {
        await userService.deleteUser(userId);
        toast.success('User deleted successfully');
        loadDashboardData(); // Refresh the data after deletion
      } catch (err) {
        console.error('Error deleting user:', err);
        toast.error('Failed to delete user');
      }
    }
  };

  const handleUpdateUser = (user) => {
    navigate(`/admin/users/${user._id}/edit`);
  };

  const handleViewUser = (user) => {
    navigate(`/admin/users/${user._id}/view`);
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Dashboard</CardTitle>
        </CardHeader>
        <CardContent>
          <Loading text="Loading dashboard data..." />
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="flex flex-1 flex-col gap-4">
      <div className="grid auto-rows-min gap-4 grid-cols-1 md:grid-cols-2 xl:grid-cols-4">
        <div className="aspect-video rounded-xl bg-muted/50 h-[130px] w-full">
          <div className="bg-cyan-500 text-white rounded-xl flex flex-col justify-between shadow overflow-hidden h-full ">
            <div className="p-3 flex justify-between">
              <div>
                <h2 className="text-4xl font-bold">{papers.length}</h2>
                <p className="mt-1 text-sm">Total Papers</p>
              </div>
              <div className="text-cyan-200 opacity-70">
                <svg
                  width="60"
                  height="60"
                  viewBox="0 0 24 24"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <rect
                    x="4"
                    y="4"
                    width="16"
                    height="16"
                    rx="2"
                    stroke="currentColor"
                    strokeWidth="2"
                  />
                  <path
                    d="M9 12L11 14L15 10"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </div>
            </div>
            <div className="bg-cyan-600 p-0 text-center">
              <Link asChild to="/admin/papers">
                <Button
                  variant="link"
                  className="text-white flex items-center justify-center w-full"
                >
                  More info <ChevronRight className="ml-1 h-4 w-4" />
                </Button>
              </Link>
            </div>
          </div>
        </div>
        <div className="aspect-video rounded-xl bg-muted/50 h-[130px] w-full">
          <div className="bg-amber-500 text-white rounded-xl flex flex-col justify-between shadow overflow-hidden h-full ">
            <div className="p-4 flex justify-between">
              <div>
                <h2 className="text-4xl font-bold">{stats.questions.total}</h2>
                <p className="mt-1 text-sm">Total Questions</p>
              </div>
              <div className="text-amber-200 opacity-70">
                <svg
                  width="60"
                  height="60"
                  viewBox="0 0 24 24"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    d="M6 4H18C19.1046 4 20 4.89543 20 6V18C20 19.1046 19.1046 20 18 20H6C4.89543 20 4 19.1046 4 18V6C4 4.89543 4.89543 4 6 4Z"
                    stroke="currentColor"
                    strokeWidth="2"
                  />
                  <path
                    d="M9 8H15M9 12H15M9 16H13"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                  />
                </svg>
              </div>
            </div>
            <div className="bg-amber-600 p-0 text-center">
              <Link asChild to="/admin/questions">
                <Button
                  variant="link"
                  className="text-white flex items-center justify-center w-full"
                >
                  More info <ChevronRight className="ml-1 h-4 w-4" />
                </Button>
              </Link>
            </div>
          </div>
        </div>

        <div className="aspect-video rounded-xl bg-muted/50 h-[130px] w-full">
          <div className="bg-emerald-500 text-white rounded-xl flex flex-col justify-between shadow overflow-hidden h-full ">
            <div className="p-4 flex justify-between">
              <div>
                <h2 className="text-4xl font-bold">{stats.users.total}</h2>
                <p className="mt-1 text-sm">Total Users</p>
              </div>
              <div className="text-emerald-200 opacity-70">
                <svg
                  width="60"
                  height="60"
                  viewBox="0 0 24 24"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    d="M17 8C17 10.2091 15.2091 12 13 12C10.7909 12 9 10.2091 9 8C9 5.79086 10.7909 4 13 4C15.2091 4 17 5.79086 17 8Z"
                    stroke="currentColor"
                    strokeWidth="2"
                  />
                  <path
                    d="M13 14C9.13401 14 6 17.134 6 21H20C20 17.134 16.866 14 13 14Z"
                    stroke="currentColor"
                    strokeWidth="2"
                  />
                </svg>
              </div>
            </div>
            <div className="bg-emerald-600 p-0 text-center">
              <Link asChild to="/admin/users">
                <Button
                  variant="link"
                  className="text-white flex items-center justify-center w-full"
                >
                  More info <ChevronRight className="ml-1 h-4 w-4" />
                </Button>
              </Link>
            </div>
          </div>
        </div>
        <div className="aspect-video rounded-xl bg-muted/50 h-[130px] w-full">
          <div className="bg-red-500 text-white rounded-xl flex flex-col justify-between shadow overflow-hidden h-full ">
            <div className="p-4 flex justify-between">
              <div>
                <h2 className="text-4xl font-bold">{groups.length}</h2>
                <p className="mt-1 text-sm">Total groups</p>
              </div>
              <div className="text-red-200 opacity-70">
                <svg
                  width="60"
                  height="60"
                  viewBox="0 0 24 24"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    d="M18 6L6 18"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                  />
                  <path
                    d="M6 6L18 18"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                  />
                </svg>
              </div>
            </div>
            <div className="bg-red-600 p-0 text-center">
              <Link asChild to="/admin/groups">
                <Button
                  variant="link"
                  className="text-white flex items-center justify-center w-full"
                >
                  More info <ChevronRight className="ml-1 h-4 w-4" />
                </Button>
              </Link>
            </div>
          </div>
        </div>
      </div>
      <div className="flex-1 gap-4 flex flex-col rounded-xl">
        <div className="grid auto-rows-min gap-4 md:grid-cols-2">
          <PieChartComp
            cardTitle={'Overall Result All Papers'}
            className="px-4"
          >
            <PieChrt totalVisitors={paperStats.total} paperStats={paperStats} />
          </PieChartComp>

          <Card className="flex flex-col h-full">
            <CardHeader className="items-center pb-4 w-full">
              <CardTitle>Total Paper attend by candidates</CardTitle>
            </CardHeader>

            <CardContent className="flex-1 pb-0">
              <div className="flex flex-col gap-2">
                <div className="flex items-center gap-2 justify-between border-b-2 mb-2">
                  <p className="font-semibold">
                    Total Paper attend by candidates
                  </p>
                  <span>{paperStats.total}</span>
                </div>
                <div className="flex items-center gap-2 justify-between border-b-2 mb-2">
                  <p className="font-semibold">Total Pass Candidates</p>
                  <span>{paperStats.pass}</span>
                </div>
                <div className="flex items-center gap-2 justify-between border-b-2 mb-2">
                  <p className="font-semibold">Total Fail Candidates</p>
                  <span>{paperStats.fail}</span>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
        <div className="grid auto-rows-min gap-4 grid-cols-1">
          <PieChartComp
            cardTitle={'Last 10 Registered Users'}
            className="px-4"
            children={
              <TableDetails
                users={users}
                groups={groups}
                onDeleteUser={handleDeleteUser}
                onUpdateUser={handleUpdateUser}
                onViewUser={handleViewUser}
              />
            }
          />
        </div>
      </div>
    </div>
  );
};

const TableDetails = React.memo(
  ({ users, groups, onDeleteUser, onUpdateUser, onViewUser }) => {
    // Get last 10 users from the users array in reverse order (newest first)
    const lastTenUsers = users?.slice(-10).reverse() || [];

    const handleDelete = async (userId) => {
      try {
        await onDeleteUser(userId);
      } catch (err) {
        console.error('Error deleting user:', err);
      }
    };

    const handleUpdate = (user) => {
      onUpdateUser(user);
    };

    const handleView = (user) => {
      onViewUser(user);
    };

    const getGroupName = (user) => {
      if (!user.group) return 'N/A';

      // Find the group in our groups array
      const group = groups.find((g) => g._id === user.group);
      return group ? group.name : 'N/A';
    };

    return (
      <div className="overflow-x-auto w-full border rounded-sm mx-auto mt-6 p-0">
        <table className="w-full p-0">
          <thead>
            <tr className="border-b">
              <th className="text-left font-bold bg-accent py-3 px-4">#</th>
              <th className="text-left font-bold bg-accent py-3 px-4">
                Full Name
              </th>
              <th className="text-left py-3 px-4 bg-accent font-bold">
                Mobile
              </th>
              <th className="text-left py-3 px-4 bg-accent font-bold">Email</th>
              <th className="text-left py-3 px-4 bg-accent font-bold">Group</th>
              <th className="text-left py-3 px-4 bg-accent font-bold">
                Status
              </th>
              <th className="text-left py-3 px-4 bg-accent font-bold">
                Actions
              </th>
            </tr>
          </thead>
          <tbody>
            {lastTenUsers.map((user, index) => (
              <tr
                key={user._id}
                className="border-b hover:bg-primary-foreground"
              >
                <td className="py-3 px-4">{index + 1}</td>
                <td className="py-3 px-4">{user.name}</td>
                <td className="py-3 px-4">{user.mobile}</td>
                <td className="py-3 px-4">{user.email}</td>
                <td className="py-3 px-4">{getGroupName(user)}</td>
                <td className="py-3 px-4">
                  <span
                    className={`font-semibold text-xs px-2 py-1 rounded ${
                      user.status === 'Active'
                        ? 'bg-green-500 text-white'
                        : 'bg-red-500 text-white'
                    }`}
                  >
                    {user.status || 'Active'}
                  </span>
                </td>
                <td className="py-3 px-4">
                  <div className="flex space-x-1">
                    <Button
                      size="icon"
                      className="h-7 w-7 bg-rose-500 hover:bg-rose-600"
                      onClick={() => handleView(user)}
                      title="View User"
                    >
                      <Search className="h-4 w-4" />
                    </Button>
                    <Button
                      size="icon"
                      className="h-7 w-7 bg-cyan-500 hover:bg-cyan-600"
                      onClick={() => handleUpdate(user)}
                      title="Edit User"
                    >
                      <Pencil className="h-4 w-4" />
                    </Button>
                    <Button
                      size="icon"
                      className="h-7 w-7 bg-orange-600 hover:bg-orange-700"
                      onClick={() => handleDelete(user._id)}
                      title="Delete User"
                    >
                      <Trash className="h-4 w-4" />
                    </Button>
                  </div>
                </td>
              </tr>
            ))}
            {lastTenUsers.length === 0 && (
              <tr>
                <td colSpan="7" className="py-4 text-center text-gray-500">
                  No users found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    );
  }
);

function PieChrt({ totalVisitors, paperStats }) {
  const [chartData, setChartData] = useState([
    { browser: 'pass', visitors: 0, fill: 'hsl(var(--chart-1))' },
    { browser: 'fail', visitors: 0, fill: 'hsl(var(--chart-2))' },
  ]);

  useEffect(() => {
    if (totalVisitors > 0) {
      const passCount = Math.round((paperStats.pass / totalVisitors) * 100);
      const failCount = 100 - passCount;

      setChartData([
        { browser: 'pass', visitors: passCount, fill: 'hsl(var(--chart-1))' },
        { browser: 'fail', visitors: failCount, fill: 'hsl(var(--chart-2))' },
      ]);
    }
  }, [totalVisitors, paperStats]);

  return (
    <ChartContainer
      config={chartConfig}
      className="mx-auto aspect-square max-h-[250px]"
    >
      <PieChart>
        <ChartTooltip
          cursor={false}
          content={<ChartTooltipContent hideLabel />}
        />
        <Pie
          data={chartData}
          dataKey="visitors"
          nameKey="browser"
          innerRadius={60}
          strokeWidth={5}
        >
          <Label
            content={({ viewBox }) => {
              if (viewBox && 'cx' in viewBox && 'cy' in viewBox) {
                return (
                  <text
                    x={viewBox.cx}
                    y={viewBox.cy}
                    textAnchor="middle"
                    dominantBaseline="middle"
                  >
                    <tspan
                      x={viewBox.cx}
                      y={viewBox.cy}
                      className="fill-foreground text-3xl font-bold"
                    >
                      {totalVisitors.toLocaleString()}
                    </tspan>
                    <tspan
                      x={viewBox.cx}
                      y={(viewBox.cy || 0) + 24}
                      className="fill-muted-foreground"
                    >
                      Total Results
                    </tspan>
                  </text>
                );
              }
            }}
          />
        </Pie>
      </PieChart>
    </ChartContainer>
  );
}

export default Dashboard;
