'use client';

import * as React from 'react';
import {
  type ColumnDef,
  type ColumnFiltersState,
  type SortingState,
  type VisibilityState,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table';
import {
  ArrowUpDown,
  Check,
  ChevronDown,
  Eye,
  Trash2,
  X,
  Pencil,
} from 'lucide-react';
import { toast } from 'react-toastify';

import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  questionService,
  type Question,
  categoryService,
  type Category,
} from '@/services/api.ts';
import { Loading } from '@/components/ui/loading';
import { ViewQuestion } from '@/components/view-question';
import { EditQuestion } from '@/components/edit-question';

export function QuestionsTable() {
  const [questions, setQuestions] = React.useState<Question[]>([]);
  const [categories, setCategories] = React.useState<Category[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>(
    []
  );
  const [columnVisibility, setColumnVisibility] =
    React.useState<VisibilityState>({});
  const [rowSelection, setRowSelection] = React.useState({});
  const [selectedQuestion, setSelectedQuestion] =
    React.useState<Question | null>(null);
  const [isViewOpen, setIsViewOpen] = React.useState(false);
  const [isEditOpen, setIsEditOpen] = React.useState(false);
  const [actionLoading, setActionLoading] = React.useState<{
    delete?: string;
    status?: string;
    view?: string;
    edit?: string;
  }>({});

  React.useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      setError(null);
      const [questionsData, categoriesData] = await Promise.all([
        questionService.getAllQuestions(),
        categoryService.getAllCategories(),
      ]);
      setQuestions(questionsData);
      setCategories(categoriesData);
    } catch (error: any) {
      setError(error.message || 'Failed to load data');
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  // Helper function to get category name by ID
  const getCategoryName = (categoryId: string) => {
    const category = categories.find((cat) => cat._id === categoryId);
    return category?.name || categoryId;
  };

  // Helper function to get subcategory name by ID
  const getSubCategoryName = (
    mainCategoryId: string,
    subCategoryId: string
  ) => {
    const category = categories.find((cat) => cat._id === mainCategoryId);
    const subCategory = category?.subCategories.find(
      (sub) => sub._id === subCategoryId
    );
    return subCategory?.name || subCategoryId;
  };

  const handleDeleteQuestion = async (questionId: string) => {
    if (window.confirm('Are you sure you want to delete this question?')) {
      try {
        setActionLoading((prev) => ({ ...prev, delete: questionId }));
        await questionService.deleteQuestion(questionId);
        toast.success('Question deleted successfully');
        loadData();
      } catch (error: any) {
        toast.error(error.message || 'Failed to delete question');
      } finally {
        setActionLoading((prev) => ({ ...prev, delete: undefined }));
      }
    }
  };

  const handleStatusToggle = async (
    questionId: string,
    currentStatus: 'Active' | 'Inactive'
  ) => {
    try {
      setActionLoading((prev) => ({ ...prev, status: questionId }));
      await questionService.updateQuestionStatus(
        questionId,
        currentStatus === 'Active' ? 'Inactive' : 'Active'
      );
      toast.success('Question status updated successfully');
      loadData();
    } catch (error: any) {
      toast.error(error.message || 'Failed to update question status');
    } finally {
      setActionLoading((prev) => ({ ...prev, status: undefined }));
    }
  };

  const handleViewQuestion = (question: Question) => {
    setActionLoading((prev) => ({ ...prev, view: question._id }));
    setSelectedQuestion(question);
    setIsViewOpen(true);
  };

  const handleEditQuestion = (question: Question) => {
    setActionLoading((prev) => ({ ...prev, edit: question._id }));
    setSelectedQuestion(question);
    setIsEditOpen(true);
  };

  const handleCloseView = () => {
    setIsViewOpen(false);
    setSelectedQuestion(null);
    setActionLoading((prev) => ({ ...prev, view: undefined }));
  };

  const handleCloseEdit = () => {
    setIsEditOpen(false);
    setSelectedQuestion(null);
    setActionLoading((prev) => ({ ...prev, edit: undefined }));
  };

  const columns: ColumnDef<Question>[] = [
    {
      accessorKey: '_id',
      header: 'ID',
      cell: ({ row }) => <div className="text-center">{row.index + 1}</div>,
    },
    {
      accessorKey: 'questionText',
      header: 'Question',
      cell: ({ row }) => (
        <div className="max-w-[500px] min-w-[300px] text-wrap">
          {row.getValue('questionText')}
        </div>
      ),
    },
    {
      accessorKey: 'answer',
      header: 'Answer',
      cell: ({ row }) => {
        const question = row.original;
        if (
          ['multiple-choice-single', 'multiple-choice-multiple'].includes(
            question.questionType
          )
        ) {
          const correctOptions =
            question.options?.filter((opt) => opt.isCorrect) || [];
          return (
            <div className="flex flex-col gap-1">
              <div className="flex flex-col gap-1">
                {correctOptions.map((opt, idx) => (
                  <div key={idx} className="text-green-600">
                    {idx + 1}. {opt.text}
                  </div>
                ))}
              </div>
            </div>
          );
        } else if (question.questionType === 'true-false') {
          return (
            <div className="flex flex-col gap-1">
              <div className="text-green-600">{question.answer || '-'}</div>
            </div>
          );
        } else if (question.questionType === 'essay') {
          return (
            <div className="flex flex-col gap-1">
              <div className="text-green-600">
                Essay Question - No specific answer
              </div>
            </div>
          );
        } else {
          return (
            <div className="flex flex-col gap-1">
              <div className="text-green-600">{question.answer || '-'}</div>
            </div>
          );
        }
      },
    },
    {
      accessorKey: 'mainCategory',
      header: 'Main Category',
      cell: ({ row }) => (
        <div>{getCategoryName(row.getValue('mainCategory'))}</div>
      ),
    },
    {
      accessorKey: 'subCategory',
      header: 'Sub Category',
      cell: ({ row }) => (
        <div>
          {getSubCategoryName(
            row.getValue('mainCategory'),
            row.getValue('subCategory')
          )}
        </div>
      ),
    },
    {
      accessorKey: 'level',
      header: 'Level',
      cell: ({ row }) => <div>{row.getValue('level')}</div>,
    },
    {
      accessorKey: 'status',
      header: 'Status',
      cell: ({ row }) => {
        const status = row.getValue('status') as string;
        return (
          <Badge
            variant={status === 'Active' ? 'default' : 'destructive'}
            className="rounded-sm px-2 py-1 text-xs font-medium"
          >
            {status}
          </Badge>
        );
      },
    },
    {
      id: 'actions',
      header: 'Actions',
      cell: ({ row }) => {
        const question = row.original;
        const isLoading = actionLoading[question._id];
        return (
          <div className="flex items-center gap-1">
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8 bg-red-50"
              onClick={() => handleDeleteQuestion(question._id)}
              disabled={isLoading}
            >
              {actionLoading.delete === question._id ? (
                <Loading size="sm" text="" />
              ) : (
                <Trash2 className="h-4 w-4 text-red-500" />
              )}
            </Button>
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8 bg-blue-50"
              onClick={() => handleViewQuestion(question)}
              disabled={isLoading}
            >
              {actionLoading.view === question._id ? (
                <Loading size="sm" text="" />
              ) : (
                <Eye className="h-4 w-4 text-blue-500" />
              )}
            </Button>
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8 bg-yellow-50"
              onClick={() => handleEditQuestion(question)}
              disabled={isLoading}
            >
              {actionLoading.edit === question._id ? (
                <Loading size="sm" text="" />
              ) : (
                <Pencil className="h-4 w-4 text-yellow-500" />
              )}
            </Button>
            <Button
              variant={question.status === 'Active' ? 'default' : 'destructive'}
              size="sm"
              className="h-8"
              onClick={() => handleStatusToggle(question._id, question.status)}
              disabled={isLoading}
            >
              {actionLoading.status === question._id ? (
                <Loading size="sm" text="" />
              ) : question.status === 'Active' ? (
                'Deactivate'
              ) : (
                'Activate'
              )}
            </Button>
          </div>
        );
      },
    },
  ];

  const table = useReactTable({
    data: questions,
    columns,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    state: {
      sorting,
      columnFilters,
      columnVisibility,
      rowSelection,
    },
  });

  if (loading) {
    return (
      <Card>
        <CardContent className="p-0">
          <div className="flex items-center justify-between p-4 border-b">
            <div className="flex items-center">
              <h1 className="text-2xl font-bold text-foreground">
                All Questions List
                <div className="text-sm font-[400] text-muted-foreground">
                  All category questions included in this List.
                </div>
              </h1>
            </div>
          </div>
          <Loading text="Loading questions..." />
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-red-500">{error}</div>
      </div>
    );
  }

  return (
    <div className="w-full">
      <Card className="pt-0">
        <CardContent className="p-0">
          <div className="flex items-center justify-between p-4 border-b">
            <div className="flex items-center">
              <h1 className="text-2xl font-bold text-foreground">
                All Questions List
                <div className="text-sm font-[400] text-muted-foreground">
                  All category questions included in this List.
                </div>
              </h1>
            </div>
            <div className="flex items-center gap-2">
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline" className="ml-auto">
                    Columns <ChevronDown className="ml-2 h-4 w-4" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  {table
                    .getAllColumns()
                    .filter((column) => column.getCanHide())
                    .map((column) => {
                      return (
                        <DropdownMenuCheckboxItem
                          key={column.id}
                          className="capitalize"
                          checked={column.getIsVisible()}
                          onCheckedChange={(value) =>
                            column.toggleVisibility(!!value)
                          }
                        >
                          {column.id}
                        </DropdownMenuCheckboxItem>
                      );
                    })}
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>
          <div className="">
            <Table>
              <TableHeader>
                {table.getHeaderGroups().map((headerGroup) => (
                  <TableRow key={headerGroup.id}>
                    {headerGroup.headers.map((header) => {
                      return (
                        <TableHead key={header.id}>
                          {header.isPlaceholder
                            ? null
                            : flexRender(
                                header.column.columnDef.header,
                                header.getContext()
                              )}
                        </TableHead>
                      );
                    })}
                  </TableRow>
                ))}
              </TableHeader>
              <TableBody>
                {table.getRowModel().rows?.length ? (
                  table.getRowModel().rows.map((row) => (
                    <TableRow
                      key={row.id}
                      data-state={row.getIsSelected() && 'selected'}
                    >
                      {row.getVisibleCells().map((cell) => (
                        <TableCell key={cell.id}>
                          {flexRender(
                            cell.column.columnDef.cell,
                            cell.getContext()
                          )}
                        </TableCell>
                      ))}
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell
                      colSpan={columns.length}
                      className="h-24 text-center"
                    >
                      No questions found.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>
          <div className="flex items-center justify-between p-4">
            <div className="text-sm text-muted-foreground">
              Showing{' '}
              {table.getState().pagination.pageIndex *
                table.getState().pagination.pageSize +
                1}{' '}
              to{' '}
              {Math.min(
                (table.getState().pagination.pageIndex + 1) *
                  table.getState().pagination.pageSize,
                questions.length
              )}{' '}
              of {questions.length} entries
            </div>
            <div className="flex items-center space-x-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => table.previousPage()}
                disabled={!table.getCanPreviousPage()}
              >
                Previous
              </Button>
              {Array.from({ length: table.getPageCount() }).map((_, index) => (
                <Button
                  key={index}
                  variant={
                    table.getState().pagination.pageIndex === index
                      ? 'default'
                      : 'outline'
                  }
                  size="sm"
                  onClick={() => table.setPageIndex(index)}
                >
                  {index + 1}
                </Button>
              ))}
              <Button
                variant="outline"
                size="sm"
                onClick={() => table.nextPage()}
                disabled={!table.getCanNextPage()}
              >
                Next
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      <ViewQuestion
        question={selectedQuestion}
        categories={categories}
        isOpen={isViewOpen}
        onClose={handleCloseView}
      />

      <EditQuestion
        question={selectedQuestion}
        categories={categories}
        isOpen={isEditOpen}
        onClose={handleCloseEdit}
        onUpdate={loadData}
      />
    </div>
  );
}

export default function QuestionsPage() {
  return (
    <div className="">
      <QuestionsTable />
    </div>
  );
}
