import axios from 'axios';

const API_URL = import.meta.env.VITE_API_URL || 'https://exam-management-ua2o.onrender.com/api';
const STATS_URL = `${API_URL}/sub-admin-stats`;

// Create axios instance with default config
const api = axios.create({
    baseURL: API_URL,
    headers: {
      'Content-Type': 'application/json',
    },
  });
  
  // Add token to requests if it exists
  api.interceptors.request.use((config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  });

const subAdminService = {
  // Get all sub-admins
  getAllSubAdmins: async () => {
    const response = await api.get('/sub-admins');
    return response.data;
  },

  // Get single sub-admin
  getSubAdmin: async (id) => {
    const response = await api.get(`/sub-admins/${id}`);
    return response.data;
  },

  // Create sub-admin
  createSubAdmin: async (subAdminData) => {
    const response = await api.post('/sub-admins', subAdminData);
    return response.data;
  },

  // Update sub-admin
  updateSubAdmin: async (id, subAdminData) => {
    const response = await api.put(`/sub-admins/${id}`, subAdminData);
    return response.data;
  },

  // Delete sub-admin
  deleteSubAdmin: async (id) => {
    const response = await api.delete(`/sub-admins/${id}`);
    return response.data;
  },

  // Stats methods
  getSubAdminStats: async (id) => {
    const response = await api.get(`/sub-admin-stats/${id}`);
    return response.data;
  },

  updateSubAdminStats: async (id, data) => {
    const response = await api.put(`/sub-admin-stats/${id}`, data);
    return response.data;
  }
};

export default subAdminService; 