'use client';

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { userService } from '@/services/api.ts';

interface User {
  _id: string;
  name: string;
  email: string;
  mobile: string;
  group: string | { _id: string; name: string };
  role: 'student' | 'teacher' | 'admin';
  status: 'Active' | 'Inactive';
  createdAt: string;
  groupName?: string;
}

interface ExamAttempt {
  _id: string;
  paperName: string;
  attemptDate: string;
  marks: number;
  percentage: number;
  result: string;
}

export default function ViewUser() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<{
    delete: boolean;
    status: boolean;
  }>({
    delete: false,
    status: false,
  });
  const [user, setUser] = useState<User | null>(null);
  const [examHistory, setExamHistory] = useState<ExamAttempt[]>([]);

  useEffect(() => {
    fetchUserData();
  }, [id]);

  const fetchUserData = async () => {
    try {
      setLoading(true);
      const userData = await userService.getUserById(id);
      setUser(userData);
      // TODO: Fetch exam history when API is available
      setExamHistory([
        {
          _id: '1',
          paperName: 'Class7-Maths',
          attemptDate: '01/02/2025 12:26:25',
          marks: 1,
          percentage: 100,
          result: 'Pass',
        },
      ]);
    } catch (error) {
      console.error('Error fetching user:', error);
      toast.error('Failed to fetch user data');
      navigate('/admin/users');
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = () => {
    navigate(`/admin/users/${id}/edit`);
  };

  const handleStatusToggle = async () => {
    try {
      setActionLoading((prev) => ({ ...prev, status: true }));
   

      const newStatus = user?.status === 'Active' ? 'Inactive' : 'Active';
      await userService.updateUser(id, { ...user, status: newStatus });
      toast.success(
        `User ${
          newStatus === 'Active' ? 'activated' : 'deactivated'
        } successfully`
      );
      fetchUserData();
    } catch (error) {
      toast.error(
        `Failed to ${
          user?.status === 'Active' ? 'deactivate' : 'activate'
        } user`
      );
    } finally {
      setActionLoading((prev) => ({ ...prev, status: false }));
    }
  };

  const handleDelete = async () => {
    if (window.confirm('Are you sure you want to delete this user?')) {
      try {
        setActionLoading((prev) => ({ ...prev, delete: true }));
        await userService.deleteUser(id);
        toast.success('User deleted successfully');
        navigate('/admin/users');
      } catch (error) {
        toast.error('Failed to delete user');
      } finally {
        setActionLoading((prev) => ({ ...prev, delete: false }));
      }
    }
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleString('en-IN', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
    });
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] p-4">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500 mb-4"></div>
        <p className="text-muted-foreground">Loading user details...</p>
      </div>
    );
  }

  if (!user) {
    return null;
  }

  return (
    <div className="p-4 space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">Full User Detail</h1>
        <div className="flex items-center gap-2">
          <Button variant="ghost" onClick={() => navigate('/admin/users')}>
            Go back
          </Button>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Complete user details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <p className="text-sm font-medium">Full Name</p>
              <p className="text-sm text-muted-foreground">{user.name}</p>
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium">Email id</p>
              <p className="text-sm text-muted-foreground">{user.email}</p>
            </div>

            <div className="space-y-1">
              <p className="text-sm font-medium">Mobile Number</p>
              <p className="text-sm text-muted-foreground">{user.mobile}</p>
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium">User Group</p>
              <p className="text-sm text-muted-foreground">{user.groupName}</p>
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium">Status</p>
              <p className="text-sm text-muted-foreground">{user.status}</p>
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium">Account created on</p>
              <p className="text-sm text-muted-foreground">
                {formatDate(user.createdAt)}
              </p>
            </div>
          </div>

          <div>
            <p className="text-sm font-medium">Notifications</p>
            <a
              href="#"
              className="text-sm text-blue-600 hover:underline"
              onClick={(e) => {
                e.preventDefault();
                // TODO: Implement resend email functionality
                toast.info('Resending email...');
              }}
            >
              Click to Resend Account details on candidate's email
            </a>
          </div>

          <div className="flex gap-2">
            <Button onClick={handleEdit}>Edit User Details</Button>
            <Button
              variant={user.status === 'Active' ? 'destructive' : 'default'}
              onClick={handleStatusToggle}
              disabled={actionLoading.status}
            >
              {actionLoading.status ? (
                <div className="flex items-center">
                  <div className="animate-spin rounded-full h-4 w-4 border-t-2 border-b-2 border-white mr-2"></div>
                  {user.status === 'Active'
                    ? 'Deactivating...'
                    : 'Activating...'}
                </div>
              ) : user.status === 'Active' ? (
                'Deactivate User'
              ) : (
                'Activate User'
              )}
            </Button>
            <Button
              variant="destructive"
              onClick={handleDelete}
              disabled={actionLoading.delete}
            >
              {actionLoading.delete ? (
                <div className="flex items-center">
                  <div className="animate-spin rounded-full h-4 w-4 border-t-2 border-b-2 border-white mr-2"></div>
                  Deleting...
                </div>
              ) : (
                'Delete User'
              )}
            </Button>
          </div>
        </CardContent>
      </Card>

      <Accordion type="single" collapsible>
        <AccordionItem value="exam-history">
          <AccordionTrigger>User Exam History</AccordionTrigger>
          <AccordionContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Sn.</TableHead>
                  <TableHead>Paper Name</TableHead>
                  <TableHead>Attempt Date Time</TableHead>
                  <TableHead>Marks</TableHead>
                  <TableHead>Percentage</TableHead>
                  <TableHead>Result</TableHead>
                  <TableHead>Action</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {examHistory.map((attempt, index) => (
                  <TableRow key={attempt._id}>
                    <TableCell>{index + 1}</TableCell>
                    <TableCell>{attempt.paperName}</TableCell>
                    <TableCell>{attempt.attemptDate}</TableCell>
                    <TableCell>{attempt.marks}</TableCell>
                    <TableCell>{attempt.percentage}%</TableCell>
                    <TableCell>{attempt.result}</TableCell>
                    <TableCell>--</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </AccordionContent>
        </AccordionItem>

        <AccordionItem value="deleted-history">
          <AccordionTrigger>Deleted Exam Attempts History</AccordionTrigger>
          <AccordionContent>
            <div className="text-center text-muted-foreground py-4">
              No deleted attempt found.
            </div>
          </AccordionContent>
        </AccordionItem>
      </Accordion>
    </div>
  );
}
