'use client';

import { useState } from 'react';
import { QuestionOptions } from './question-options';
import { QuestionForm } from './question-form';
import type { QuestionOptions as QuestionOptionsType } from './question-options';
import React from 'react';

export function QuestionBuilder() {
  const [step, setStep] = useState(1);
  const [options, setOptions] = useState<QuestionOptionsType | null>(null);

  const handleNext = (selectedOptions: QuestionOptionsType) => {
    setOptions(selectedOptions);
    setStep(2);
  };

  const handleBack = () => {
    setStep(1);
  };

  const handleSubmit = (formData: any) => {
    setStep(1);
    setOptions(null);
  };

  return (
    <div className="w-full ">
      <div className="max-w-5xl mx-auto">
        {step === 1 && <QuestionOptions onNext={handleNext} />}
        {step === 2 && options && (
          <QuestionForm
            options={options}
            onBack={handleBack}
            onSubmit={handleSubmit}
          />
        )}
      </div>
    </div>
  );
}
