'use client';

import React, { useState, useEffect } from 'react';
import type { ColumnDef } from '@tanstack/react-table';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { DataTable } from '@/components/data-table/data-table';
import { DataTableColumnHeader } from '@/components/data-table/data-table-column-header';
import { DataTableRowActions } from '@/components/data-table/data-table-row-actions';
import { StatusBadge } from '@/components/data-table/status-badge';
import { Button } from '@/components/ui/button';
import { groupService } from '@/services/api.ts';

interface Group {
  _id: string;
  name: string;
  description?: string;
  status: 'Active' | 'Inactive';
  totalUsers: number;
  createdAt: string;
}

export function GroupsTable() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [groups, setGroups] = useState<Group[]>([]);

  useEffect(() => {
    fetchGroups();
  }, []);

  const fetchGroups = async () => {
    try {
      setLoading(true);
      const response = await groupService.getAllGroups();
      setGroups(response);
    } catch (error) {
      toast.error('Failed to fetch groups');
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (group: Group) => {
    navigate(`/admin/groups/${group._id}/edit`);
  };

  const handleDelete = async (group: Group) => {
    if (window.confirm('Are you sure you want to delete this group?')) {
      try {
        await groupService.deleteGroup(group._id);
        toast.success('Group deleted successfully');
        fetchGroups();
      } catch (error) {
        toast.error('Failed to delete group');
      }
    }
  };

  const handleActivate = async (group: Group) => {
    try {
      await groupService.updateGroup(group._id, { ...group, status: 'Active' });
      toast.success('Group activated successfully');
      fetchGroups();
    } catch (error) {
      toast.error('Failed to activate group');
    }
  };

  // Define columns
  const columns: ColumnDef<Group>[] = [
    {
      accessorKey: '_id',
      header: 'Sr No.',
      cell: ({ row }) => <div>{row.index + 1}</div>,
    },
    {
      accessorKey: 'name',
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Group Name" />
      ),
      cell: ({ row }) => (
        <div className="font-medium">{row.original.name || '-'}</div>
      ),
    },
    {
      accessorKey: 'totalUsers',
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Total Users" />
      ),
      cell: ({ row }) => (
        <div className="text-center">{row.original.totalUsers}</div>
      ),
    },
    {
      accessorKey: 'status',
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Status" />
      ),
      cell: ({ row }) => <StatusBadge status={row.original.status} />,
      filterFn: (row, id, value) => {
        return value.includes(row.getValue(id));
      },
    },
    {
      id: 'actions',
      header: 'Actions',
      cell: ({ row }) => (
        <DataTableRowActions
          row={row}
          onEdit={handleEdit}
          onDelete={handleDelete}
          onActivate={
            row.original.status === 'Inactive' ? handleActivate : undefined
          }
        />
      ),
    },
  ];

  if (loading) {
    return (
      <div className="p-6 bg-background rounded-md">
        <div className="flex justify-center items-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 bg-background rounded-md">
      <div className="flex justify-between items-center mb-4">
        <div>
          <h2 className="text-2xl font-bold">All Groups List</h2>
          <p className="text-sm text-muted-foreground">
            Complete group list which is related to institute
          </p>
        </div>
        <div className="flex gap-2">
          <Button onClick={() => navigate('/admin/groups/add')}>
            Add New Group
          </Button>
        </div>
      </div>
      <DataTable columns={columns} data={groups} />
    </div>
  );
}
