import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Home, Minus, Settings, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { toast } from 'react-toastify';
import { instituteService } from '@/services/api.ts';

export default function Account() {
  const [isEditing, setIsEditing] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [instituteData, setInstituteData] = useState({
    email: '',
    registrationLink: '',
    loginLink: '',
    licenseLimit: '',
    timezone: '(UTC +5:30) Indian Standard Time, Sri Lanka Time',
    shortName: '',
    fullName: '',
    directorName: 'NA',
    address: '',
    district: '',
    state: 'NA',
    pinCode: '',
    contactNumber: '',
    directorPicture: null,
    logo: null,
    about: '',
    services: '',
  });
  // email: 'test@tech.anubhavi.in',
  // registrationLink: 'https://exam.techanubhavi.in/registration/new/460',
  // loginLink: 'https://exam.techanubhavi.in/login/institute/460',
  // licenseLimit: '100',
  // timezone: '(UTC +5:30) Indian Standard Time, Sri Lanka Time',
  // shortName: 'Tech Anubhavi',
  // fullName: 'Tech Anubhavi',
  // directorName: 'NA',
  // address: 'Vadodara',
  // district: 'Vadodara',
  // state: 'NA',
  // pinCode: '123123',
  // contactNumber: '8849681211',
  // directorPicture: null,
  // logo: null,
  // about: '',
  // services: '',
  useEffect(() => {
    fetchInstituteData();
  }, []);

  const fetchInstituteData = async () => {
    try {
      const data = await instituteService.getInstitute();
      setInstituteData(data);
      setIsLoading(false);
    } catch (error) {
      toast.error('Error fetching institute data');
      setIsLoading(false);
    }
  };

  const handleChange = (field, value) => {
    setInstituteData({
      ...instituteData,
      [field]: value,
    });
  };

  const handleSave = async () => {
    try {
      await instituteService.updateInstitute(instituteData);
      toast.success('Institute details updated successfully');
      setIsEditing(false);
    } catch (error) {
      toast.error('Error updating institute details');
    }
  };

  const handleCancel = () => {
    fetchInstituteData(); // Reset to original data
    setIsEditing(false);
  };

  const handleFileUpload = async (file, type) => {
    try {
      const uploadFunction = type === 'logo' ? instituteService.uploadLogo : instituteService.uploadDirectorPicture;
      const response = await uploadFunction(file);
      handleChange(type, response.url);
      toast.success(`${type === 'logo' ? 'Logo' : 'Director picture'} uploaded successfully`);
    } catch (error) {
      toast.error(`Error uploading ${type === 'logo' ? 'logo' : 'director picture'}`);
    }
  };

  if (isLoading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="min-h-screen">
      {/* Header */}

      {/* Main Content */}
      <main className="container mx-auto p-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <div>
              <CardTitle className="text-xl font-bold text-green-900">
                Tech Anubhavi
              </CardTitle>
              <CardDescription>Complete Details</CardDescription>
            </div>
            <div className="flex space-x-2">
              {isEditing ? (
                <>
                  <Button
                    onClick={handleSave}
                    className="bg-green-500 hover:bg-green-600"
                  >
                    Save Details
                  </Button>
                  <Button variant="outline" onClick={handleCancel}>
                    Cancel
                  </Button>
                </>
              ) : (
                <Button
                  onClick={() => setIsEditing(true)}
                  className="bg-green-500 hover:bg-green-600"
                >
                  Edit Details
                </Button>
              )}
            </div>
          </CardHeader>
          <CardContent className="pt-4">
            <div className="space-y-0 divide-y">
              {/* Institute Email ID */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute Email id</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <Input
                      value={instituteData.email}
                      onChange={(e) => handleChange('email', e.target.value)}
                    />
                  ) : (
                    <span style={{ overflowWrap: 'anywhere' }}>
                      {instituteData.email}
                    </span>
                  )}
                </div>
              </div>

              {/* Direct Registration Link */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Direct Registration Link</div>
                <div className="col-span-2 flex items-center gap-2">
                  {isEditing ? (
                    <div className="flex w-full items-center gap-2">
                      <Input
                        value={instituteData.registrationLink}
                        onChange={(e) =>
                          handleChange('registrationLink', e.target.value)
                        }
                        className="flex-1"
                      />
                      <Button variant="ghost" size="icon">
                        <Settings className="h-4 w-4" />
                      </Button>
                    </div>
                  ) : (
                    <>
                      <span style={{ overflowWrap: 'anywhere' }}>
                        {instituteData.registrationLink}
                      </span>
                      <Button variant="ghost" size="icon">
                        <Settings className="h-4 w-4" />
                      </Button>
                    </>
                  )}
                </div>
              </div>

              {/* Login Link */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">
                  Login Link with Institute Details
                </div>
                <div className="col-span-2">
                  {isEditing ? (
                    <Input
                      value={instituteData.loginLink}
                      onChange={(e) =>
                        handleChange('loginLink', e.target.value)
                      }
                    />
                  ) : (
                    <span style={{ overflowWrap: 'anywhere' }}>
                      {instituteData.loginLink}
                    </span>
                  )}
                </div>
              </div>

              {/* License Details */}
              <div className="grid grid-cols-3 py-3 text-white">
                <div className="font-medium">
                  License Details (Candidate Limit)
                </div>
                <div className="col-span-2">
                  {isEditing ? (
                    <Input
                      value={instituteData.licenseLimit}
                      onChange={(e) =>
                        handleChange('licenseLimit', e.target.value)
                      }
                      className="bg-blue-500 text-white placeholder:text-blue-200 border-blue-400"
                    />
                  ) : (
                    instituteData.licenseLimit
                  )}
                </div>
              </div>

              {/* Timezone */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute Timezone</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <Select
                      defaultValue={instituteData.timezone}
                      onValueChange={(value) => handleChange('timezone', value)}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select timezone" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="(UTC +5:30) Indian Standard Time, Sri Lanka Time">
                          (UTC +5:30) Indian Standard Time, Sri Lanka Time
                        </SelectItem>
                        <SelectItem value="(UTC +0:00) Greenwich Mean Time">
                          (UTC +0:00) Greenwich Mean Time
                        </SelectItem>
                        <SelectItem value="(UTC -5:00) Eastern Time">
                          (UTC -5:00) Eastern Time
                        </SelectItem>
                      </SelectContent>
                    </Select>
                  ) : (
                    <div className="flex items-center gap-2">
                      <span>{instituteData.timezone}</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Short Name */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute Short Name</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <Input
                      value={instituteData.shortName}
                      onChange={(e) =>
                        handleChange('shortName', e.target.value)
                      }
                    />
                  ) : (
                    instituteData.shortName
                  )}
                </div>
              </div>

              {/* Full Name */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute Full Name</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <Input
                      value={instituteData.fullName}
                      onChange={(e) => handleChange('fullName', e.target.value)}
                    />
                  ) : (
                    instituteData.fullName
                  )}
                </div>
              </div>

              {/* Director Name */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute Director Name</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <Input
                      value={instituteData.directorName}
                      onChange={(e) =>
                        handleChange('directorName', e.target.value)
                      }
                    />
                  ) : (
                    instituteData.directorName
                  )}
                </div>
              </div>

              {/* Complete Address */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute Complete Address</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <div className="space-y-3">
                      <Input
                        value={instituteData.address}
                        onChange={(e) =>
                          handleChange('address', e.target.value)
                        }
                        placeholder="Address"
                      />
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <Label htmlFor="district" className="text-xs">
                            District:
                          </Label>
                          <Input
                            id="district"
                            value={instituteData.district}
                            onChange={(e) =>
                              handleChange('district', e.target.value)
                            }
                          />
                        </div>
                        <div>
                          <Label htmlFor="state" className="text-xs">
                            State:
                          </Label>
                          <Input
                            id="state"
                            value={instituteData.state}
                            onChange={(e) =>
                              handleChange('state', e.target.value)
                            }
                          />
                        </div>
                      </div>
                      <div>
                        <Label htmlFor="pinCode" className="text-xs">
                          Pin Code:
                        </Label>
                        <Input
                          id="pinCode"
                          value={instituteData.pinCode}
                          onChange={(e) =>
                            handleChange('pinCode', e.target.value)
                          }
                        />
                      </div>
                    </div>
                  ) : (
                    <div>
                      <div>{instituteData.address}</div>
                      <div>
                        <span className="font-medium">District:</span>{' '}
                        {instituteData.district}
                      </div>
                      <div>
                        <span className="font-medium">State:</span>{' '}
                        {instituteData.state}
                        <span className="font-medium ml-4">Pin Code:</span>{' '}
                        {instituteData.pinCode}
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {/* Contact Number */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute Contact Number</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <Input
                      value={instituteData.contactNumber}
                      onChange={(e) =>
                        handleChange('contactNumber', e.target.value)
                      }
                    />
                  ) : (
                    instituteData.contactNumber
                  )}
                </div>
              </div>

              {/* Director Picture */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute's Director Picture</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <div className="flex items-center gap-2">
                      <Input 
                        type="file" 
                        className="flex-1"
                        onChange={(e) => {
                          const file = e.target.files?.[0];
                          if (file) {
                            handleFileUpload(file, 'directorPicture');
                          }
                        }}
                      />
                      <Button variant="outline" size="sm">
                        <Upload className="h-4 w-4 mr-2" /> Upload
                      </Button>
                    </div>
                  ) : (
                    instituteData.directorPicture ? (
                      <img 
                        src={instituteData.directorPicture} 
                        alt="Director" 
                        className="w-20 h-20 object-cover rounded"
                      />
                    ) : (
                      <span className="text-red-500">
                        Not available right now. Please upload.
                      </span>
                    )
                  )}
                </div>
              </div>

              {/* Institute Logo */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute logo</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <div className="flex items-center gap-2">
                      <Input 
                        type="file" 
                        className="flex-1"
                        onChange={(e) => {
                          const file = e.target.files?.[0];
                          if (file) {
                            handleFileUpload(file, 'logo');
                          }
                        }}
                      />
                      <Button variant="outline" size="sm">
                        <Upload className="h-4 w-4 mr-2" /> Upload
                      </Button>
                    </div>
                  ) : (
                    instituteData.logo ? (
                      <img 
                        src={instituteData.logo} 
                        alt="Logo" 
                        className="w-20 h-20 object-contain"
                      />
                    ) : (
                      <span className="text-red-500">
                        Not available right now. Please update.
                      </span>
                    )
                  )}
                </div>
              </div>

              {/* About */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute - About</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <Textarea
                      value={instituteData.about}
                      onChange={(e) => handleChange('about', e.target.value)}
                      placeholder="Enter information about the institute"
                      className="min-h-[100px]"
                    />
                  ) : (
                    instituteData.about ? (
                      <span style={{ whiteSpace: 'pre-line' }}>{instituteData.about}</span>
                    ) : (
                      <span className="text-red-500">
                        Not available right now. Please update.
                      </span>
                    )
                  )}
                </div>
              </div>

              {/* Services */}
              <div className="grid grid-cols-3 py-3">
                <div className="font-medium">Institute - Services</div>
                <div className="col-span-2">
                  {isEditing ? (
                    <Textarea
                      value={instituteData.services}
                      onChange={(e) => handleChange('services', e.target.value)}
                      placeholder="Enter services offered by the institute"
                      className="min-h-[100px]"
                    />
                  ) : (
                    instituteData.services ? (
                      <span style={{ whiteSpace: 'pre-line' }}>{instituteData.services}</span>
                    ) : (
                      <span className="text-red-500">
                        Not available right now. Please update.
                      </span>
                    )
                  )}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      </main>
    </div>
  );
}
