'use client';

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { AddPaperFormWithoutZod } from './add-paper-form-without-zod';
import { paperService } from '@/services/api';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';

export function EditPaper() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [paper, setPaper] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadPaper();
  }, [id]);

  const loadPaper = async () => {
    try {
      if (!id) return;
      const response = await paperService.getPaperById(id);
      setPaper(response);
    } catch (error) {
      toast.error('Failed to load paper');
      navigate('/papers');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900"></div>
      </div>
    );
  }

  if (!paper) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-red-500">Paper not found</div>
      </div>
    );
  }

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between">
        <CardTitle>Edit Paper</CardTitle>
        <Button variant="outline" onClick={() => navigate('/admin/all-papers')}>
          Back to Papers
        </Button>
      </CardHeader>
      <CardContent>
        <AddPaperFormWithoutZod initialData={paper} isEditing={true} />
      </CardContent>
    </Card>
  );
}

export default EditPaper; 