export const paperService = {
  getAllPapers: async (): Promise<Paper[]> => {
    try {
      const response = await api.get('/papers');
      return response.data;
    } catch (error: any) {
      if (error.response?.status === 401) {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        window.location.href = '/login';
        throw new Error('Session expired. Please login again.');
      }
      throw error.response?.data || error;
    }
  },

  createPaper: async (paperData: Omit<Paper, '_id'>): Promise<Paper> => {
    try {
      const response = await api.post('/papers', paperData);
      return response.data;
    } catch (error: any) {
      if (error.response?.status === 401) {
        // Token expired or invalid
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        window.location.href = '/login';
        throw new Error('Session expired. Please login again.');
      }
      throw error.response?.data || error;
    }
  },

  deletePaper: async (id: string): Promise<void> => {
    try {
      await api.delete(`${API_URL}/papers/${id}`);
    } catch (error: any) {
      throw error.response?.data || error;
    }
  },

  updatePaperStatus: async (
    id: string,
    status: 'Active' | 'Deactive'
  ): Promise<Paper> => {
    const response = await api.patch(`${API_URL}/papers/${id}/status`, {
      status,
    });
    return response.data;
  },

  editPaper: async (id: string, paperData: Partial<Paper>): Promise<Paper> => {
    try {
      const response = await api.put(`${API_URL}/papers/${id}`, paperData);
      return response.data;
    } catch (error) {
      if (error.response?.status === 401) {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        window.location.href = '/login';
        throw new Error('Session expired. Please login again.');
      }
      throw error;
    }
  },

  getPaperById: async (id: string): Promise<Paper> => {
    try {
      const response = await api.get(`/papers/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.status === 401) {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        window.location.href = '/login';
        throw new Error('Session expired. Please login again.');
      }
      throw error;
    }
  },

  addQuestionsToPaper: async (
    paperId: string,
    questionIds: string[]
  ): Promise<Paper> => {
    try {
      const response = await api.post(`/papers/${paperId}/questions`, {
        questions: questionIds,
      });
      return response.data;
    } catch (error: any) {
      if (error.response?.status === 401) {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        window.location.href = '/login';
        throw new Error('Session expired. Please login again.');
      }
      throw error;
    }
  },

  getPaperQuestions: async (paperId: string): Promise<Question[]> => {
    try {
      const response = await axios.get(
        `${API_URL}/papers/${paperId}/questions`,
        {
          headers: {
            'x-auth-token': localStorage.getItem('token'),
          },
        }
      );
      return response.data;
    } catch (error: any) {
      if (error.response?.status === 401) {
        localStorage.removeItem('token');
        window.location.href = '/login';
        throw new Error('Session expired. Please login again.');
      }
      throw error;
    }
  },

  updatePaper: async (
    id: string,
    paperData: Partial<Paper>
  ): Promise<Paper> => {
    try {
      const response = await api.put(`${API_URL}/papers/${id}`, paperData);
      return response.data;
    } catch (error) {
      if (error.response?.status === 401) {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        window.location.href = '/login';
        throw new Error('Session expired. Please login again.');
      }
      throw error;
    }
  },
};

