import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { examService } from '../services/api';
import { Loading } from '@/components/ui/loading';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

function StudentDashboard() {
  const [exams, setExams] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    loadExams();
  }, []);

  const loadExams = async () => {
    try {
      const data = await examService.getAllExams();
      // Filter only published exams
      const publishedExams = data.filter((exam) => exam.status === 'published');
      setExams(publishedExams);
    } catch (error) {
      toast.error('Error loading exams');
      console.error('Error:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleStartExam = (examId) => {
    navigate(`/student/take-exam/${examId}`);
  };

  const handleViewResult = (examId) => {
    navigate(`/student/exam-result/${examId}`);
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Student Dashboard</CardTitle>
        </CardHeader>
        <CardContent>
          <Loading text="Loading available exams..." />
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-2xl font-bold mb-6">Available Exams</h1>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {exams.map((exam) => (
          <div
            key={exam._id}
            className="bg-white rounded-lg shadow-md p-6 space-y-4"
          >
            <h2 className="text-xl font-semibold">{exam.title}</h2>
            <p className="text-gray-600">{exam.description}</p>

            <div className="space-y-2">
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Subject:</span>
                <span className="font-medium">{exam.subject}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Duration:</span>
                <span className="font-medium">{exam.duration} minutes</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Total Marks:</span>
                <span className="font-medium">{exam.totalMarks}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Passing Marks:</span>
                <span className="font-medium">{exam.passingMarks}</span>
              </div>
            </div>

            <div className="flex justify-between items-center pt-4">
              <button
                onClick={() => handleStartExam(exam._id)}
                className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
              >
                Start Exam
              </button>
              <button
                onClick={() => handleViewResult(exam._id)}
                className="text-blue-500 hover:text-blue-700"
              >
                View Results
              </button>
            </div>
          </div>
        ))}
      </div>

      {exams.length === 0 && (
        <div className="text-center text-gray-500 mt-8">
          No exams are currently available.
        </div>
      )}
    </div>
  );
}

export default StudentDashboard;
