'use client';

import * as React from 'react';
import { TrendingUp } from 'lucide-react';

import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';

const PieChartComp = ({
  className,
  cardTitle,
  cardDescription,
  children,
  ...props
}) => {
  return (
    <Accordion
      type="single"
      defaultValue="item-1"
      collapsible
      className="w-full"
      {...props}
    >
      <Card className={`${className} flex flex-col h-full`}>
        <AccordionItem className="h-full" value="item-1">
          <CardHeader className="items-center pb-0 w-full">
            <CardTitle>{cardTitle ? cardTitle : ''}</CardTitle>

            <CardDescription>
              {cardDescription ? cardDescription : ''}
            </CardDescription>
          </CardHeader>

          <AccordionContent>
            <CardContent className="flex-1 pb-0 w-full overflow-x-auto p-0">
              {children}
            </CardContent>
          </AccordionContent>
        </AccordionItem>
      </Card>
    </Accordion>
  );
};
export default PieChartComp;
