import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { examService } from '../services/api';
import { Loading } from '@/components/ui/loading';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

function TeacherDashboard() {
  const [exams, setExams] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem('user'));

  useEffect(() => {
    loadExams();
  }, []);

  const loadExams = async () => {
    try {
      const data = await examService.getTeacherExams(user.id);
      setExams(data);
    } catch (error) {
      toast.error('Error loading exams');
      console.error('Error:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateExam = () => {
    navigate('/teacher/create-exam');
  };

  const handleEditExam = (examId) => {
    navigate(`/teacher/edit-exam/${examId}`);
  };

  const handleDeleteExam = async (examId) => {
    if (window.confirm('Are you sure you want to delete this exam?')) {
      try {
        await examService.deleteExam(examId);
        toast.success('Exam deleted successfully');
        loadExams();
      } catch (error) {
        toast.error('Error deleting exam');
        console.error('Error:', error);
      }
    }
  };

  const handleViewResults = (examId) => {
    navigate(`/teacher/exam-results/${examId}`);
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Teacher Dashboard</CardTitle>
        </CardHeader>
        <CardContent>
          <Loading text="Loading teacher dashboard..." />
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Teacher Dashboard</h1>
        <button
          onClick={handleCreateExam}
          className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
        >
          Create New Exam
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {exams.map((exam) => (
          <div
            key={exam._id}
            className="bg-white rounded-lg shadow-md p-6 space-y-4"
          >
            <h2 className="text-xl font-semibold">{exam.title}</h2>
            <p className="text-gray-600">{exam.description}</p>
            <div className="flex justify-between items-center">
              <span className="text-sm text-gray-500">
                Subject: {exam.subject}
              </span>
              <span
                className={`text-sm ${
                  exam.status === 'published'
                    ? 'text-green-500'
                    : 'text-yellow-500'
                }`}
              >
                {exam.status}
              </span>
            </div>
            <div className="flex space-x-4 mt-4">
              <button
                onClick={() => handleEditExam(exam._id)}
                className="text-blue-500 hover:text-blue-700"
              >
                Edit
              </button>
              <button
                onClick={() => handleDeleteExam(exam._id)}
                className="text-red-500 hover:text-red-700"
              >
                Delete
              </button>
              <button
                onClick={() => handleViewResults(exam._id)}
                className="text-green-500 hover:text-green-700"
              >
                View Results
              </button>
            </div>
          </div>
        ))}
      </div>

      {exams.length === 0 && (
        <div className="text-center text-gray-500 mt-8">
          No exams created yet. Click the button above to create your first
          exam.
        </div>
      )}
    </div>
  );
}

export default TeacherDashboard;
