'use client';

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { userService, groupService } from '@/services/api.ts';

interface User {
  _id: string;
  name: string;
  email: string;
  mobile: string;
  group: string;
  role: 'student' | 'teacher' | 'admin';
  status: 'Active' | 'Inactive';
}

interface Group {
  _id: string;
  name: string;
}

interface ApiUser {
  _id: string;
  name: string;
  email: string;
  mobile: string;
  group: string;
  role: string;
  status: string;
}

export default function EditUser() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [groups, setGroups] = useState<Group[]>([]);
  const [formData, setFormData] = useState<User>({
    _id: '',
    name: '',
    email: '',
    mobile: '',
    group: '',
    role: 'student',
    status: 'Active',
  });

  useEffect(() => {
    fetchUserData();
    fetchGroups();
  }, [id]);

  const fetchUserData = async () => {
    try {
      setLoading(true);
      const userData = await userService.getUserById(id);
      console.log('Fetched user data:', userData);
      setFormData({
        _id: userData._id,
        name: userData.name,
        email: userData.email,
        mobile: userData.mobile,
        group:
          typeof userData.group === 'object'
            ? userData.group._id
            : userData.group,
        role: userData.role as 'student' | 'teacher' | 'admin',
        status: userData.status as 'Active' | 'Inactive',
      });
    } catch (error) {
      console.error('Error fetching user:', error);
      toast.error('Failed to fetch user data');
      navigate('/admin/users');
    } finally {
      setLoading(false);
    }
  };

  const fetchGroups = async () => {
    try {
      const data = await groupService.getAllGroups();
      setGroups(data);
    } catch (error) {
      console.error('Error fetching groups:', error);
      toast.error('Failed to load groups');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      await userService.updateUser(id, formData);
      toast.success('User updated successfully');
      navigate('/admin/users');
    } catch (error) {
      toast.error(error.message || 'Failed to update user');
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSelectChange = (
    field: keyof Pick<User, 'role' | 'status' | 'group'>,
    value: string
  ) => {
    setFormData((prev) => ({
      ...prev,
      [field]: value as User[typeof field],
    }));
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return (
    <div className="p-4">
      <Card className="border-t-4 border-t-primary">
        <CardHeader className="border-b px-6 py-4">
          <div className="flex justify-between items-center">
            <CardTitle className="text-lg font-medium text-foreground/80">
              <h1 className="text-2xl font-bold text-foreground">Edit User</h1>
              <p className="text-sm text-muted-foreground">
                Update user information
              </p>
            </CardTitle>
          </div>
        </CardHeader>

        <CardContent className="p-6 space-y-6">
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name" className="font-medium text-foreground">
                Full Name
              </Label>
              <Input
                id="name"
                name="name"
                placeholder="Enter full name"
                value={formData.name}
                onChange={handleChange}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="email" className="font-medium text-foreground">
                Email
              </Label>
              <Input
                id="email"
                name="email"
                type="email"
                placeholder="Enter email address"
                value={formData.email}
                onChange={handleChange}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="mobile" className="font-medium text-foreground">
                Mobile
              </Label>
              <Input
                id="mobile"
                name="mobile"
                placeholder="Enter mobile number"
                value={formData.mobile}
                onChange={handleChange}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="group" className="font-medium text-foreground">
                Group
              </Label>
              <Select
                value={formData.group}
                onValueChange={(value) => handleSelectChange('group', value)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select a group" />
                </SelectTrigger>
                <SelectContent>
                  {groups.map((group) => (
                    <SelectItem key={group._id} value={group._id}>
                      {group.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="role" className="font-medium text-foreground">
                Role
              </Label>
              <Select
                value={formData.role}
                onValueChange={(value) => handleSelectChange('role', value)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select a role" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="student">Student</SelectItem>
                  <SelectItem value="teacher">Teacher</SelectItem>
                  <SelectItem value="admin">Admin</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="status" className="font-medium text-foreground">
                Status
              </Label>
              <Select
                value={formData.status}
                onValueChange={(value) => handleSelectChange('status', value)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Active">Active</SelectItem>
                  <SelectItem value="Inactive">Inactive</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="flex justify-center w-full gap-4 pt-4">
              <Button type="submit" className="w-1/2" disabled={loading}>
                {loading ? 'Updating...' : 'Update User'}
              </Button>
              <Button
                type="button"
                variant="outline"
                className="w-1/2"
                onClick={() => navigate('/admin/users')}
              >
                Cancel
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}
