'use client';

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { ChevronDown, ChevronUp, Download, Home } from 'lucide-react';
import { toast } from 'react-toastify';
import * as XLSX from 'xlsx';
import { questionService } from '@/services/api.ts';
import { categoryService } from '@/services/api.ts';

import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/components/ui/collapsible';

export default function BulkQuestionUpload() {
  const [isOpen, setIsOpen] = useState(true);
  const [fileName, setFileName] = useState<string | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [format, setFormat] = useState<'single' | 'dual'>('single');
  const [mainCategory, setMainCategory] = useState<string>('');
  const [subCategory, setSubCategory] = useState<string>('');
  const [categories, setCategories] = useState<Array<{ _id: string; name: string; subCategories: Array<{ _id: string; name: string }> }>>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const data = await categoryService.getAllCategories();
        setCategories(data);
      } catch (error) {
        toast.error('Failed to load categories');
        console.error('Error loading categories:', error);
      }
    };
    fetchCategories();
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setFileName(file.name);
      setSelectedFile(file);
    } else {
      setFileName(null);
      setSelectedFile(null);
    }
  };

  const handleUpload = async () => {
    if (!selectedFile || !mainCategory || !subCategory) {
      toast.error('Please select a file and categories');
      return;
    }

    try {
      setLoading(true);
      const reader = new FileReader();
      reader.onload = async (e) => {
        try {
          const data = e.target?.result;
          const workbook = XLSX.read(data, { type: 'binary' });
          const sheetName = workbook.SheetNames[0];
          const worksheet = workbook.Sheets[sheetName];
          const jsonData = XLSX.utils.sheet_to_json(worksheet);

          const questions = jsonData.map((row: any) => ({
            questionText: row.questionText,
            questionType: row.questionType || 'multiple-choice',
            options: row.options ? JSON.parse(row.options) : [],
            marks: Number(row.marks) || 1,
            explanation: row.explanation || '',
            mainCategory,
            subCategory,
            level: row.level || 'top-simple',
          }));

          await questionService.bulkCreateQuestions('', questions);
          toast.success('Questions uploaded successfully');
          setFileName(null);
          setSelectedFile(null);
        } catch (error) {
          toast.error('Error processing file');
          console.error('Error processing file:', error);
        }
      };
      reader.readAsBinaryString(selectedFile);
    } catch (error) {
      toast.error('Error uploading file');
      console.error('Error uploading file:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadSample = (type: 'single' | 'dual') => {
    const sampleData = [
      {
        questionText: 'Sample Question',
        questionType: 'multiple-choice',
        options: JSON.stringify([
          { text: 'Option 1', isCorrect: true },
          { text: 'Option 2', isCorrect: false },
          { text: 'Option 3', isCorrect: false },
          { text: 'Option 4', isCorrect: false }
        ]),
        marks: 1,
        explanation: 'Sample explanation',
        level: 'top-simple'
      }
    ];

    const ws = XLSX.utils.json_to_sheet(sampleData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Questions');
    XLSX.writeFile(wb, `sample_questions_${type}.xlsx`);
  };

  return (
    <div className="border rounded-md shadow-sm bg-background">
      <div className="flex justify-between items-center border-b border-muted-foreground p-4">
        <h1 className="text-2xl font-semibold text-foreground flex flex-wrap gap-y-0 gap-2 items-baseline">
          Bulk Question Upload{' '}
          <span className="text-sm font-normal text-muted-foreground">
            Upload questions via Excel File
          </span>
        </h1>
      </div>
      <div className="flex justify-between items-center p-4 cursor-pointer">
        <h2 className="text-lg font-light text-foreground/80">
          Bulk upload facility
        </h2>
      </div>

      <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-6">
          <div className="space-y-2">
            <label htmlFor="excel-format" className="block text-sm font-medium">
              Excel Format
            </label>
            <Select defaultValue="single">
              <SelectTrigger id="excel-format" className="w-full">
                <SelectValue placeholder="Select format" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="single">Single Language</SelectItem>
                <SelectItem value="dual">Dual Language</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <label htmlFor="category" className="block text-sm font-medium">
              Select Category{' '}
              <span className="text-gray-400">- - - - - - -</span>{' '}
              <Link to={'#'} className="text-primary text-xs">
                Click to Add new Category
              </Link>
            </label>
            <Select>
              <SelectTrigger id="category" className="w-full">
                <SelectValue placeholder="Select main category" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="category1">Category 1</SelectItem>
                <SelectItem value="category2">Category 2</SelectItem>
                <SelectItem value="category3">Category 3</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <label htmlFor="subcategory" className="block text-sm font-medium">
              Sub Category <span className="text-gray-400">- - - - - -</span>{' '}
              <Link to={'#'} className="text-primary text-xs">
                Click to Add new Subcategory
              </Link>
            </label>
            <Select>
              <SelectTrigger id="subcategory" className="w-full">
                <SelectValue placeholder="Select Sub category" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="subcategory1">Subcategory 1</SelectItem>
                <SelectItem value="subcategory2">Subcategory 2</SelectItem>
                <SelectItem value="subcategory3">Subcategory 3</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <label htmlFor="file-upload" className="block text-sm font-medium">
              Upload File
            </label>
            <div className="flex items-center gap-2">
              <label htmlFor="file-upload" className="cursor-pointer">
                <div className="px-4 py-2 border rounded bg-muted text-sm">
                  Choose File
                </div>
                <input
                  id="file-upload"
                  type="file"
                  accept=".xlsx,.xls"
                  className="hidden"
                  onChange={handleFileChange}
                />
              </label>
              <span className="text-sm text-gray-500">
                {fileName || 'No file chosen'}
              </span>
            </div>
          </div>

          <Button className="bg-emerald-500 hover:bg-emerald-600 text-white">
            Upload Now
          </Button>
        </div>

        <div className="flex flex-col gap-4">
          <Button
            variant="default"
            className="bg-purple-600 hover:bg-purple-700 text-white !text-wrap flex items-center gap-2 justify-center py-6"
          >
            <Download className="h-5 w-5" />
            Download Sample Excel File (Single Language)
          </Button>

          <Button
            variant="default"
            className="bg-purple-600 hover:bg-purple-700 !text-wrap text-white flex items-center gap-2 justify-center py-6"
          >
            <Download className="h-5 w-5" />
            Download Sample Excel File (Dual Language)
          </Button>
        </div>
      </div>
    </div>
  );
}
