import Account from './components/Account.jsx';
import {
  BrowserRouter,
  Route,
  Routes,
  Outlet,
  useLocation,
  Link,
  Navigate,
} from 'react-router-dom';
import Dashboard from './components/Dashboard';
import { AppSidebar } from '@/components/app-sidebar';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb';
import { Separator } from '@/components/ui/separator';
import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from '@/components/ui/sidebar';
import Notifications from './components/Notifications';
import { useCookies } from 'react-cookie';
import AddQuestionForm from './components/add-question-form';
import CategoriesSection from './components/categories-section';
import AddNewSubAdmin from './components/add-new-subAdmin';
import BulkUsersUpload from './components/bulk-user-upload';
import AddNewUser from './components/add-new-user';
import LoginForm from './components/Login';
import QuestionsTable from './components/questions-table';
import BulkQuestionUpload from './components/bulk-question-upload';
import AddNewGroup from './components/add-new-group';
import { PaperDataTable } from './components/All-papers';
import { SubAdminsTable } from '@/components/sub-admins';
import { GroupsTable } from '@/components/groups-table';
import { UsersDataTable } from '@/components/users/users-data-table';
import { AddPaperFormWithoutZod } from './components/papers/add-paper-form-without-zod.tsx';
import { EditPaper } from './components/papers/edit-paper';
import { fetchPapers } from './data/papers';
import { useEffect, useState } from 'react';
import { toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import TeacherDashboard from './components/TeacherDashboard';
import CreateExam from './components/CreateExam';
import StudentDashboard from './components/StudentDashboard';
import ViewUser from './components/users/view-user.tsx';
import EditUser from './components/users/edit-user';
import { AddQuestionsToPaper } from './components/papers/add-questions-to-paper';
import { authService } from './services/api';
import EditGroup from './components/edit-group';
import ViewSubAdmin from './components/view-subAdmin.jsx';
import EditSubAdmin from './components/edit-subAdmin.jsx';
// Protected Route wrapper
const ProtectedRoute = ({ children, allowedRoles }) => {
  if (!authService.isAuthenticated()) {
    return <Navigate to="/login" replace />;
  }

  const user = authService.getUser();
  if (allowedRoles && !allowedRoles.includes(user.role)) {
    return <Navigate to="/" replace />;
  }

  return children;
};

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(
    authService.isAuthenticated()
  );
  const [papers, setPapers] = useState([]);

  useEffect(() => {
    const loadPapers = async () => {
      try {
        const fetchedPapers = await fetchPapers();
        setPapers(fetchedPapers);
      } catch (error) {
        console.error('Error loading papers:', error);
        toast.error('Failed to load papers');
      }
    };

    if (isAuthenticated) {
      loadPapers();
    }
  }, [isAuthenticated]);

  const handleLoginSuccess = () => {
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    authService.logout();
    toast.info('Logged out successfully', {
      position: 'top-right',
      autoClose: 3000,
      onClose: () => {
        window.location.href = '/login';
      },
    });
    setIsAuthenticated(false);
  };

  return (
    <BrowserRouter>
      <ToastContainer position="top-right" autoClose={3000} />
      <Routes>
        {/* Root Route with Auth Check */}
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <Aside onLogout={handleLogout}>
                <Dashboard />
              </Aside>
            </ProtectedRoute>
          }
        />

        {/* Public Routes */}
        <Route
          path="/login"
          element={<LoginForm onLoginSuccess={handleLoginSuccess} />}
        />

        {/* Admin Routes */}
        <Route
          path="/admin/*"
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <Aside onLogout={handleLogout}>
                <Outlet />
              </Aside>
            </ProtectedRoute>
          }
        >
          <Route path="dashboard" element={<Dashboard />} />
          <Route path="users" element={<UsersDataTable />} />
          <Route path="users/add" element={<AddNewUser />} />
          <Route path="users/bulk-upload" element={<BulkUsersUpload />} />
          <Route path="users/:id/view" element={<ViewUser />} />
          <Route path="users/:id/edit" element={<EditUser />} />
          <Route path="sub-admins" element={<SubAdminsTable />} />
          <Route path="sub-admins/add" element={<AddNewSubAdmin />} />
          <Route path="sub-admins/:id" element={<ViewSubAdmin />} />
          <Route path="sub-admins/:id/edit" element={<EditSubAdmin />} />
          <Route path="groups" element={<GroupsTable />} />
          <Route path="groups/add" element={<AddNewGroup />} />
          <Route path="groups/:id/edit" element={<EditGroup />} />
          <Route path="questions" element={<QuestionsTable />} />
          <Route path="questions/add" element={<AddQuestionForm />} />
          <Route
            path="questions/bulk-upload"
            element={<BulkQuestionUpload />}
          />
          <Route path="papers" element={<PaperDataTable />} />
          <Route path="papers/add" element={<AddPaperFormWithoutZod />} />
          <Route path="papers/:id/edit" element={<EditPaper />} />
          <Route
            path="papers/:id/add-questions"
            element={<AddQuestionsToPaper />}
          />
          <Route path="categories" element={<CategoriesSection />} />
          <Route path="notifications" element={<Notifications />} />
          <Route path="account" element={<Account />} />
        </Route>

        {/* Teacher Routes */}
        <Route
          path="/teacher/*"
          element={
            <ProtectedRoute allowedRoles={['teacher', 'admin']}>
              <Aside onLogout={handleLogout}>
                <Outlet />
              </Aside>
            </ProtectedRoute>
          }
        >
          <Route path="dashboard" element={<TeacherDashboard />} />
          <Route path="create-exam" element={<CreateExam />} />
        </Route>

        {/* Student Routes */}
        <Route
          path="/student/*"
          element={
            <ProtectedRoute allowedRoles={['student']}>
              <Aside onLogout={handleLogout}>
                <Outlet />
              </Aside>
            </ProtectedRoute>
          }
        >
          <Route path="dashboard" element={<StudentDashboard />} />
        </Route>

        {/* Catch-all route */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </BrowserRouter>
  );
}

function Aside({ onLogout }) {
  const [cookies, setCookie] = useCookies(['sidebar_state']);
  const defaultOpen = cookies.sidebar_state;
  const location = useLocation();
  const [user, setUser] = useState(authService.getUser());
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        if (!authService.isAuthenticated()) {
          onLogout();
          return;
        }

        const userData = await authService.getCurrentUser();
        setUser(userData);
      } catch (error) {
        console.error('Error fetching user data:', error);
        if (error.response?.status === 401) {
          onLogout();
          return;
        }
        // Only show error message for non-auth errors
        toast.error('Failed to fetch user data. Please try again.');
      } finally {
        setLoading(false);
      }
    };

    fetchUserData();
  }, [onLogout]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  // Only render the sidebar if we have user data
  if (!user) {
    return null;
  }


  return (
    <SidebarProvider defaultOpen={defaultOpen}>
      <AppSidebar onLogout={onLogout} user={user} />
      <SidebarInset style={{ width: 'calc(100% - var(--sidebar-width))' }}>
        <header className="sticky top-0 z-20 bg-sidebar flex h-16 shrink-0 items-center gap-2 transition-[width,height] ease-linear group-has-[[data-collapsible=icon]]/sidebar-wrapper:h-12">
          <div className="flex items-center gap-2 px-4">
            <SidebarTrigger
              onClick={() => setCookie(!defaultOpen)}
              className="-ml-1"
            />
            <Separator orientation="vertical" className="mr-2 h-4" />

            <Breadcrumb>
              <BreadcrumbList>
                <BreadcrumbItem>
                  {location.pathname === '/' ? (
                    <BreadcrumbPage>Dashboard</BreadcrumbPage>
                  ) : (
                    <BreadcrumbLink>
                      <Link 
                        to={user?.role === 'admin' ? '/admin/dashboard' : 
                            user?.role === 'teacher' ? '/teacher/dashboard' : 
                            user?.role === 'student' ? '/student/dashboard' : '/'} 
                        className="cursor-pointer p-2 rounded-md"
                      >
                        Dashboard
                      </Link>
                    </BreadcrumbLink>
                  )}
                </BreadcrumbItem>

              

                {/* Users Section */}
                {location.pathname.includes('/admin/users') && (
                  <>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      {location.pathname === '/admin/users' ? (
                        <BreadcrumbPage>Users</BreadcrumbPage>
                      ) : (
                        <BreadcrumbLink>
                          <Link to="/admin/users" className="cursor-pointer p-2 rounded-md">
                            Users
                          </Link>
                        </BreadcrumbLink>
                      )}
                    </BreadcrumbItem>
                    {location.pathname.includes('/admin/users/add') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Add User</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                    {location.pathname.includes('/admin/users/bulk-upload') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Bulk Upload</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                  </>
                )}

                {/* Questions Section */}
                {location.pathname.includes('/admin/questions') && (
                  <>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      {location.pathname === '/admin/questions' ? (
                        <BreadcrumbPage>Questions</BreadcrumbPage>
                      ) : (
                        <BreadcrumbLink>
                          <Link to="/admin/questions" className="cursor-pointer p-2 rounded-md">
                            Questions
                          </Link>
                        </BreadcrumbLink>
                      )}
                    </BreadcrumbItem>
                    {location.pathname.includes('/admin/questions/add') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Add Question</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                    {location.pathname.includes('/admin/questions/bulk-upload') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Bulk Upload</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                  </>
                )}

                {/* Papers Section */}
                {location.pathname.includes('/admin/papers') && (
                  <>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      {location.pathname === '/admin/papers' ? (
                        <BreadcrumbPage>Papers</BreadcrumbPage>
                      ) : (
                        <BreadcrumbLink>
                          <Link to="/admin/papers" className="cursor-pointer p-2 rounded-md">
                            Papers
                          </Link>
                        </BreadcrumbLink>
                      )}
                    </BreadcrumbItem>
                    {location.pathname.includes('/admin/papers/add') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Add Paper</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                    {location.pathname.includes('/admin/papers/edit') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Edit Paper</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                  </>
                )}

                {/* Sub Admins Section */}
                {location.pathname.includes('/admin/sub-admins') && (
                  <>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      {location.pathname === '/admin/sub-admins' ? (
                        <BreadcrumbPage>Sub Admins</BreadcrumbPage>
                      ) : (
                        <BreadcrumbLink>
                          <Link to="/admin/sub-admins" className="cursor-pointer p-2 rounded-md">
                            Sub Admins
                          </Link>
                        </BreadcrumbLink>
                      )}
                    </BreadcrumbItem>
                    {location.pathname.includes('/admin/sub-admins/add') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Add Sub Admin</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                  </>
                )}

                {/* Groups Section */}
                {location.pathname.includes('/admin/groups') && (
                  <>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      {location.pathname === '/admin/groups' ? (
                        <BreadcrumbPage>Groups</BreadcrumbPage>
                      ) : (
                        <BreadcrumbLink>
                          <Link to="/admin/groups" className="cursor-pointer p-2 rounded-md">
                            Groups
                          </Link>
                        </BreadcrumbLink>
                      )}
                    </BreadcrumbItem>
                    {location.pathname.includes('/admin/groups/add') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Add Group</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                    {location.pathname.includes('/admin/groups/edit') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Edit Group</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                  </>
                )}

                {/* Categories Section */}
                {location.pathname.includes('/admin/categories') && (
                  <>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      <BreadcrumbPage>Categories</BreadcrumbPage>
                    </BreadcrumbItem>
                  </>
                )}

                {/* Notifications Section */}
                {location.pathname.includes('/admin/notifications') && (
                  <>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      <BreadcrumbPage>Notifications</BreadcrumbPage>
                    </BreadcrumbItem>
                  </>
                )}

                {/* Account Section */}
                {location.pathname.includes('/admin/account') && (
                  <>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      <BreadcrumbPage>Account</BreadcrumbPage>
                    </BreadcrumbItem>
                  </>
                )}

                {/* Teacher Routes */}
                {location.pathname.startsWith('/teacher') && (
                  <>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      <BreadcrumbPage>Teacher</BreadcrumbPage>
                    </BreadcrumbItem>
                    {location.pathname.includes('/teacher/dashboard') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Dashboard</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                    {location.pathname.includes('/teacher/create-exam') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Create Exam</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                  </>
                )}

                {/* Student Routes */}
                {location.pathname.startsWith('/student') && (
                  <>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      <BreadcrumbPage>Student</BreadcrumbPage>
                    </BreadcrumbItem>
                    {location.pathname.includes('/student/dashboard') && (
                      <>
                        <BreadcrumbSeparator />
                        <BreadcrumbItem>
                          <BreadcrumbPage>Dashboard</BreadcrumbPage>
                        </BreadcrumbItem>
                      </>
                    )}
                  </>
                )}
              </BreadcrumbList>
            </Breadcrumb>
          </div>
        </header>
        <div className="p-4 bg-sidebar w-full h-full">
          <Outlet />
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

export default App;
