'use client';

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { toast } from 'react-toastify';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { groupService } from '@/services/api.ts';

export default function EditGroup() {
  const navigate = useNavigate();
  const { id } = useParams();
  const [formData, setFormData] = useState({
    name: '',
    totalUsers: 0,
    status: 'Active',
  });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchGroup();
  }, [id]);

  const fetchGroup = async () => {
    try {
      const group = await groupService.getAllGroups();
      const currentGroup = group.find((g) => g._id === id);
      if (currentGroup) {
        setFormData({
          name: currentGroup.name,
          totalUsers: currentGroup.totalUsers,
          status: currentGroup.status,
        });
      }
    } catch (error) {
      toast.error(error.message || 'Failed to fetch group details');
      navigate('/admin/groups');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await groupService.updateGroup(id, formData);
      toast.success('Group updated successfully');
      navigate('/admin/groups');
    } catch (error) {
      toast.error(error.message || 'Failed to update group');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4">
      <Card className="border-t-4 border-t-primary">
        <CardHeader className="border-b px-6 py-4">
          <div className="flex justify-between items-center">
            <CardTitle className="text-lg font-medium text-foreground/80">
              <h1 className="text-2xl font-bold text-foreground">Edit Group</h1>
              <p className="text-sm text-muted-foreground">
                Update group information
              </p>
            </CardTitle>
          </div>
        </CardHeader>

        <CardContent className="p-6 space-y-6">
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name" className="font-medium text-foreground">
                Group Name
              </Label>
              <Input
                id="name"
                placeholder="Enter group name"
                value={formData.name}
                onChange={(e) =>
                  setFormData({ ...formData, name: e.target.value })
                }
                required
              />
            </div>

            <div className="space-y-2">
              <Label
                htmlFor="totalUsers"
                className="font-medium text-foreground"
              >
                Total Users
              </Label>
              <Input
                id="totalUsers"
                type="number"
                min="0"
                placeholder="Enter total number of users"
                value={formData.totalUsers}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    totalUsers: parseInt(e.target.value) || 0,
                  })
                }
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="status" className="font-medium text-foreground">
                Status
              </Label>
              <Select
                value={formData.status}
                onValueChange={(value) =>
                  setFormData({ ...formData, status: value })
                }
              >
                <SelectTrigger id="status" className="w-full">
                  <SelectValue placeholder="Select status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Active">Active</SelectItem>
                  <SelectItem value="Inactive">Inactive</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="flex justify-end space-x-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => navigate('/admin/groups')}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={loading}>
                {loading ? 'Updating...' : 'Update Group'}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}
